INSERT INTO public.learning_paths (id, slug, name, emoji, subtitle, short_description, long_description, is_active, position)
VALUES ('a8c62c04-79e0-42f7-aebe-0e0a9899cb1b', 'ecosistema-ethereum', 'Ecosistema Ethereum', '📜', 'Leer un contrato antes de firmarlo', 'Qué añadió la red que ejecuta programas, qué cuesta ejecutar, quién puede cambiar un contrato después de que lo hayas revisado y qué estás firmando exactamente.', 'Casi todo lo que se llama «cripto» y no es Bitcoin vive en redes que no anotan pagos: ejecutan programas. Esta ruta describe qué cambia con eso, sin recomendar ninguna red, ninguna aplicación ni ningún token.

El hilo es una pregunta que la mayoría de las explicaciones deja sin responder: **¿quién puede cambiar esto después de que lo hayas revisado, y qué hace falta para que lo cambie?** Alrededor de ella se ordenan el coste de ejecutar, los datos de fuera de los que todo depende, las cuatro formas por las que el dinero sale de un contrato y lo que ocurre cuando firmas.

No enseña a programar y no sirve para saber si algo va a funcionar. Sirve para saber de qué depende.', TRUE, 6)
ON CONFLICT (id) DO NOTHING;

-- ============================================================================
-- 2. El curso
-- ============================================================================

INSERT INTO public.courses (id, slug, title, description, long_description, status, level, is_free, price, is_premium, total_modules, total_lessons, instructor_id)
VALUES ('d6f814e2-26d6-4d72-8e01-ce224fcde3f5', 'ethereum-y-contratos-inteligentes', 'Ethereum y contratos inteligentes', 'Qué cambia cuando una red ejecuta programas en vez de anotar pagos. El coste de ejecutar, quién puede cambiar un contrato y qué estás firmando.', 'Un contrato no es inteligente, no es un contrato y muchas veces no es inmutable. Este curso explica qué es en realidad: un programa con fondos propios, publicado en un registro que ejecuta, ciego a todo lo que ocurre fuera de él y cuyo comportamiento puede cambiar alguien sin modificar una sola instrucción.

Empieza por lo que añadió esta red —cuentas con estado, el cobro por ejecutar, y las cuatro cosas que un programa de estos no puede hacer por diseño—. Sigue por lo que de verdad decide si algo sale mal: de dónde sale el código que se ejecuta, quién puede cambiar las reglas después, y las cuatro formas por las que el dinero sale de un contrato, dos de las cuales no son fallos de nada. Y termina en lo práctico: qué ocurre cuando firmas, las unidades que prometen valer un euro, y un método de seis preguntas que se responden mirando el contrato.

**Requisito previo:** haber hecho *Blockchain: lo que Bitcoin no es* y *Qué es Web3 y qué no*. Este curso da por sabidos la diferencia entre anotar movimientos y mantener un estado, qué garantiza y qué no garantiza un contrato, y que firmar no es una sola cosa. Sin esa base resulta incómodo.

No hace falta saber programar. No se recomienda ninguna red, ninguna aplicación ni ningún token, y no se habla de precios ni de rendimientos.', 'published', 'intermediate', TRUE, 0, FALSE, 3, 9, '34c7dd0a-3854-4b76-8d11-16cd778e3269')
ON CONFLICT (id) DO NOTHING;

