-- 1.1 de-un-registro-a-un-ordenador-compartido (8722 car)
INSERT INTO public.lessons (id, course_id, module_id, title, slug, description, order_index, content)
VALUES ('7cd8049c-90f1-46f7-8acd-5e7ae8b7b457', 'd6f814e2-26d6-4d72-8e01-ce224fcde3f5', '3b2cb791-1ebd-4490-ad11-28f420361e2a', 'De un registro a un ordenador compartido', 'de-un-registro-a-un-ordenador-compartido', 'Qué hay en una cuenta, las dos clases que existen, y la pieza sin equivalente en Bitcoin: un programa puede tener fondos propios.', 0, '<h3>🎯 Objetivo de la lección</h3><p>Ver qué cambia, en concreto, cuando una red mantiene un estado en vez de anotar movimientos. Que existen los dos tipos ya lo sabes; aquí se ve el segundo funcionando, y aparece la pieza que no tiene equivalente en nada de lo anterior: <strong>un programa puede tener fondos propios</strong>.</p><hr><h3>🧭 Qué da por sabido este curso, y qué no hace</h3><p>Este curso se apoya en dos, no en uno, y conviene decirlo antes de empezar.</p><p>De <em>Blockchain: lo que Bitcoin no es</em> da por sabida la diferencia entre <strong>anotar movimientos y mantener un estado</strong> (lección 1.3) y la costumbre de preguntar «¿a cambio de qué?» ante cualquier diseño. De <em>Qué es Web3 y qué no</em> da por sabido qué es un contrato y qué no garantiza, que una aplicación de estas es contratos más una web corriente, y que <strong>firmar no es una sola cosa</strong>.</p><p>Si eso no te suena, este curso te va a resultar incómodo. Es mejor hacer aquellos antes.</p><p>Lo que hace este es bajar al caso concreto, y sobre todo <strong>responder la pregunta que el otro dejó abierta</strong>. Allí aprendiste a preguntar «¿quién puede cambiar este contrato y qué hace falta para que lo haga?». Aprender a preguntarla no es saber responderla, y el módulo 2 de este curso se dedica a eso.</p><p>Lo que no hace: <strong>no enseña a programar</strong>, no recomienda ninguna red, ninguna aplicación ni ningún token, y no habla de precios ni de rendimientos.</p><hr><h3>🧩 De qué pregunta salió</h3><p>Bitcoin resolvió un problema estrecho, y lo estrechó a propósito: <em>cuanto menos puede hacer el sistema, más fácil es comprobar que hace lo que dice</em>. Ya conoces la frase.</p><p>La pregunta que se planteó en 2013 —y que arrancó como red en 2015— no fue «cómo hacer Bitcoin más rápido». Fue otra, y es la que explica todo lo que viene:</p><p><strong>Si ya sabemos poner de acuerdo a desconocidos sobre un registro compartido, ¿por qué ese registro solo puede anotar pagos?</strong></p><p>La propuesta fue un registro que mantenga <em>cualquier</em> estado y ejecute programas que lo modifiquen. Y el precio ya sabes nombrarlo: cómputo, tamaño del estado y superficie de fallo.</p><p>Así que <strong>no es «Bitcoin mejorado»</strong>. No se plantearon el mismo problema, y comparar cuál lo resuelve mejor es comparar dos respuestas a dos preguntas distintas.</p><hr><h3>🗂️ Qué hay en una cuenta</h3><p>En Bitcoin el saldo es un cálculo: se suma lo que puedes gastar. Aquí es una casilla, y eso ya lo viste. Lo que no viste es <strong>qué más hay en esa casilla</strong>.</p><p>Cada cuenta guarda tres cosas:</p><ul><li><p><strong>Un saldo.</strong> La cantidad de la moneda nativa de la red, el <em>ether</em>, que tiene esa cuenta.</p></li><li><p><strong>Un contador de operaciones</strong> hechas desde ella. Sirve para fijar el orden y para que la misma orden no se ejecute dos veces. Tiene consecuencias prácticas molestas, y es la lección 3.1.</p></li><li><p><strong>Y, si la cuenta es un programa: su código y su propia memoria.</strong></p></li></ul><p>Ese tercer punto es toda la diferencia.</p><hr><h3>🤖 Dos clases de cuentas</h3><p><strong>Las que abre una clave.</strong> Como en Bitcoin: generas una clave y la cuenta existe. Nadie la crea, nadie la aprueba, no hay registro. Firmando con la clave ordenas operaciones.</p><p><strong>Las que son un programa.</strong> Tienen código y memoria propia, y <strong>no tienen clave</strong>: nadie puede firmar en su nombre, ni el que lo escribió. A cambio hay algo que sorprende:</p><p><strong>Un programa de estos no puede empezar nada.</strong> No vigila, no espera y no se despierta. Solo se ejecuta cuando alguien lo llama desde fuera y paga por la llamada.</p><p>Vale la pena detenerse, porque explica cosas que luego parecen raras. Si algo tiene que pasar a una hora determinada —cerrar un plazo, liquidar una posición, repartir algo—, <strong>alguien de fuera tiene que llamar a esa hora</strong>. De ahí que existan servicios cuyo único trabajo sea apretar botones a su hora. Y de ahí que esos servicios sean un punto de fallo del que casi nadie habla.</p><hr><h3>💰 La pieza nueva: un programa con fondos</h3><p>Esto es lo que no tiene equivalente en nada de lo anterior.</p><p>En Bitcoin los fondos están siempre bloqueados a una condición: quien la cumpla puede gastarlos. Aquí <strong>una de las cuentas con saldo puede ser un programa entero</strong>, con su memoria y sus reglas, y la gente le manda fondos.</p><p>Tres consecuencias, y son las que ordenan el curso:</p><ul><li><p><strong>Puedes depositar en algo que no es nadie.</strong> No hay una persona al otro lado, ni una empresa, ni una cuenta a nombre de alguien. Hay un texto ejecutándose.</p></li><li><p><strong>Lo que ocurra con ese depósito depende de ese texto.</strong> Si tiene un fallo, el fallo se ejecuta con la misma obediencia que el resto.</p></li><li><p><strong>No hay a quién reclamar.</strong> Ya lo sabías dicho de otra forma: se ejecuta sin interpretar nada y sin tribunal al que acudir. Visto desde aquí, es más literal de lo que parecía.</p></li></ul><p>No es un defecto ni una virtud: es el intercambio. Todo el módulo 2 trata de leerlo antes de aceptarlo.</p><hr><h3>⛓️ Entera o nada</h3><p>Una sola operación tuya puede desencadenar muchas cosas: un programa que llama a otro, que modifica dos casillas, que comprueba una tercera.</p><p>La regla es simple: <strong>o pasa todo o no pasa nada</strong>. Si algo falla a mitad, el estado vuelve exactamente a como estaba, como si no se hubiera intentado. No quedan operaciones a medias.</p><p>Con una excepción que sorprende a casi todo el mundo, y que es la lección siguiente: <strong>el intento se paga igual</strong>. Deshacer el resultado no deshace el trabajo que hizo la red para llegar hasta ahí.</p><hr><h3>⛽ Por qué hace falta ether para todo</h3><p>Ejecutar cuesta, y se paga en ether. También cuando lo que mueves no es ether.</p><p>De ahí una situación que la gente descubre en mal momento: <strong>puedes tener un token y no poder moverlo</strong>. Mover un token es llamar a un programa, y llamar a un programa se paga en la moneda nativa. Sin ether en esa cuenta, lo que hay dentro no se mueve.</p><p>No es un fallo ni una trampa. Es la consecuencia directa de que aquí el registro no anota pagos: <strong>ejecuta</strong>, y la ejecución se cobra.</p><hr><h3>🚫 Tres ideas que conviene soltar</h3><p><strong>«Es Bitcoin mejorado.»</strong> Es otra máquina, respondiendo a otra pregunta. La frase del otro curso sirve igual: no es una mejora de la misma cosa, es otra cosa con otro precio.</p><p><strong>«El ether es solo una moneda.»</strong> Es además la unidad con la que se paga el cómputo de toda la red. Sin ella nada se ejecuta, y eso le da un papel que el bitcoin no tiene en Bitcoin.</p><p><strong>«Los contratos son de esta red.»</strong> No: el mecanismo es general y hay varias redes con estado que lo tienen. Aquí se usa esta porque es la más documentada y la que más gente se encuentra, <strong>no porque sea la mejor ni la única</strong>. Lo del módulo 2 y el método del final sirven para cualquiera de ellas.</p><hr><h3>📌 En resumen</h3><ul><li><p>Este curso da por sabidos <em>Blockchain: lo que Bitcoin no es</em> y <em>Qué es Web3 y qué no</em>, y se dedica a <strong>responder la pregunta que el segundo dejó abierta</strong>: quién puede cambiar un contrato y qué hace falta.</p></li><li><p>La pregunta de origen no fue cómo mejorar Bitcoin, sino <strong>por qué un registro compartido solo podía anotar pagos</strong>.</p></li><li><p>Una cuenta guarda <strong>saldo</strong>, un <strong>contador de operaciones</strong> y —si es un programa— <strong>código y memoria propia</strong>.</p></li><li><p>Hay dos clases de cuentas: las que abre una clave y las que <strong>son un programa</strong>. Estas no tienen clave y <strong>no pueden empezar nada</strong>: alguien de fuera tiene que llamarlas.</p></li><li><p>La pieza sin equivalente: <strong>un programa puede tener fondos</strong>. Depositas en algo que no es nadie, lo que pase depende de un texto, y no hay a quién reclamar.</p></li><li><p>Una operación <strong>pasa entera o no pasa</strong>, pero <strong>el intento se paga igual</strong>.</p></li><li><p>Ejecutar se paga en ether, así que <strong>puedes tener un token y no poder moverlo</strong>.</p></li></ul><hr><h3>➡️ Qué viene después</h3><p>Queda por explicar lo que se acaba de dar por supuesto tres veces: <strong>que ejecutar cuesta y quién lo paga</strong>. La lección siguiente entra en cómo se cobra el cómputo, por qué una operación se queda a medias y se paga igual, y por qué una red muy usada expulsa antes al que tiene poco.</p>')
ON CONFLICT (id) DO NOTHING;

-- 1.2 quien-paga-la-ejecucion (8051 car)
INSERT INTO public.lessons (id, course_id, module_id, title, slug, description, order_index, content)
VALUES ('109347ca-a50b-44fb-b827-1784de94e7c5', 'd6f814e2-26d6-4d72-8e01-ce224fcde3f5', '3b2cb791-1ebd-4490-ad11-28f420361e2a', 'Quién paga la ejecución', 'quien-paga-la-ejecucion', 'Por qué se cobra por ejecutar, por qué un intento fallido se paga igual, y por qué una red muy usada deja fuera al usuario pequeño.', 1, '<h3>🎯 Objetivo de la lección</h3><p>Entender cómo se cobra la ejecución: por qué se paga por operación y no por cantidad movida, qué significa el número que te muestran antes de firmar, por qué un intento fallido se paga igual, y por qué una red muy usada expulsa antes al que tiene poco.</p><hr><h3>⚖️ Por qué hay que cobrar por ejecutar</h3><p>Si la red ejecuta programas que le mandan desde fuera, hay un problema evidente: <strong>nada impide mandarle un programa que no termine nunca</strong>. Un bucle sin salida, y todos los que mantienen una copia se quedan colgados.</p><p>La solución es poner precio a cada paso. Cada operación elemental —sumar, comparar, guardar un dato, llamar a otro programa— tiene un coste fijado por el propio protocolo, medido en una unidad de trabajo. El que ordena la ejecución <strong>declara cuánto trabajo está dispuesto a pagar como máximo</strong>, y cuando se agota, la ejecución se para.</p><p>Así que el cobro no es una forma de ganar dinero: <strong>es el mecanismo que impide que la red se quede bloqueada</strong>. Es la misma idea que la prueba de trabajo de Bitcoin —hacer que participar cueste—, aplicada a otra cosa.</p><hr><h3>🧮 Dos números distintos</h3><p>Cuando te muestran un coste, detrás hay dos cifras que conviene no confundir, porque cambian por motivos distintos.</p><p><strong>Cuánto trabajo cuesta.</strong> Lo fija el protocolo, no el mercado. Mover ether cuesta poco. Llamar a un programa cuesta más. Y hay una jerarquía que explica muchas sorpresas: <strong>leer es barato, escribir es caro, y escribir en una casilla que antes estaba vacía es lo más caro de todo</strong>. Ocupar sitio nuevo en el estado es lo que más cuesta, porque es lo que todos los que mantienen una copia van a tener que guardar para siempre.</p><p><strong>Cuánto se paga por cada unidad de trabajo.</strong> Esto sí es mercado, y cambia cada pocos segundos. Tiene dos partes: una que <strong>fija el propio protocolo según lo llena que vaya la red</strong> —sube cuando hay demanda, baja cuando no la hay, y se destruye en vez de pagarse a nadie— y una propina para quien te incluya.</p><p>El total es el producto de las dos. De ahí que la misma operación cueste distinto un martes por la mañana y un domingo por la noche, <strong>sin que haya cambiado nada de lo que haces</strong>.</p><hr><h3>🔎 Una distinción que ahorra confusiones: leer no cuesta</h3><p>Consultar el estado —ver un saldo, leer qué dice una casilla de un contrato— <strong>no cuesta nada y no requiere firmar</strong>, porque no modifica nada: es una pregunta a una copia del registro, no una orden a la red.</p><p>Solo se paga lo que <strong>cambia el estado</strong>. Es la línea que separa mirar de actuar, y es la misma línea que separa lo que no tiene riesgo de lo que sí.</p><hr><h3>💥 Lo que pasa cuando se agota</h3><p>Aquí está el detalle que la lección anterior dejó anunciado, y es el que más desconcierta.</p><p>Si la ejecución consume todo el trabajo que declaraste y no ha terminado, <strong>se detiene y el estado vuelve a como estaba</strong>. Nada de lo que iba a pasar pasa. Y aun así <strong>se paga todo lo consumido</strong>.</p><p>No es un abuso. Los que mantienen la red hicieron el trabajo de ejecutar hasta ahí: deshacer el resultado no deshace el esfuerzo. Si el intento fallido fuera gratis, <strong>atacar la red sería gratis</strong>: bastaría con mandar operaciones destinadas a fallar.</p><p>Y al revés, si sobra: solo se paga lo que se usó de verdad. Declarar un máximo alto no encarece nada por sí mismo; solo fija el techo de lo que puedes llegar a perder si algo va mal.</p><p>Dos consecuencias prácticas:</p><ul><li><p><strong>Una operación puede costarte dinero sin haber conseguido nada.</strong> Y es la situación normal, no un fallo del sistema.</p></li><li><p><strong>El número que te muestra una aplicación es una estimación.</strong> Se calcula simulando la ejecución con el estado de ahora, y el estado puede haber cambiado cuando te toque el turno. Si cambia lo suficiente, la estimación se queda corta.</p></li></ul><hr><h3>🚪 Por qué expulsa antes al que tiene poco</h3><p>Esta es la consecuencia más importante de la lección, y la que menos se cuenta.</p><p><strong>El coste depende de lo que la red tenga que hacer, no de cuánto mueves.</strong> Enviar el equivalente a cinco euros y enviar el equivalente a cincuenta mil cuesta exactamente lo mismo.</p><p>Es decir: es un <strong>peaje fijo</strong>. Y un peaje fijo no afecta a todos igual. Si el peaje sube hasta acercarse a lo que quieres mover, tu operación deja de tener sentido, mientras que para quien mueve mil veces más sigue siendo irrelevante.</p><p>Así que cuando una de estas redes se pone cara, <strong>no se encarece para todos: deja fuera a los de abajo</strong>. Primero las operaciones pequeñas, después las medianas. Los que mueven mucho ni lo notan.</p><p>Y eso choca con casi todo lo que se promete alrededor de estas redes: <strong>una red muy usada es una red en la que el usuario pequeño no cabe</strong>. De ahí viene el interés por mover actividad fuera de la cadena principal, que ya viste en <em>Blockchain</em>: no es una mejora opcional, es la respuesta a este problema.</p><hr><h3>🔁 La pregunta de siempre, aplicada aquí</h3><p>Se podría abaratar la ejecución. Basta con cobrar menos por cada paso o dejar entrar más operaciones en cada bloque. ¿A cambio de qué?</p><p>A cambio de que el estado crezca más rápido y ejecutar cueste más trabajo, de modo que <strong>mantener una copia completa sea más caro y menos gente pueda hacerlo</strong>. Y menos copias independientes es menos gente comprobando.</p><p>Es exactamente la tensión que ya tienes nombrada: velocidad y coste contra apertura y verificación. <strong>Ninguna red ha escapado de ella</strong>; solo eligen en qué punto quedarse.</p><hr><h3>🧭 Qué mirar antes de firmar</h3><p>Sin entrar en cómo se hace nada, tres cosas que el número de la pantalla te está diciendo:</p><ul><li><p><strong>Cuánto puedes perder como máximo si falla.</strong> No es el coste estimado: es el techo que declaras.</p></li><li><p><strong>Si el coste es desproporcionado respecto a lo que crees que estás haciendo</strong>, probablemente no estás haciendo lo que crees. Una operación sencilla que cuesta mucho está tocando más cosas de las que esperas.</p></li><li><p><strong>Cuánto costaría deshacerlo o salir.</strong> Entrar y salir se pagan por separado, y hay situaciones en las que salir cuesta más que entrar.</p></li></ul><hr><h3>📌 En resumen</h3><ul><li><p>Se cobra por ejecutar <strong>para que nadie pueda bloquear la red</strong> mandándole trabajo infinito. No es un modelo de negocio, es una defensa.</p></li><li><p>Detrás del coste hay dos números: <strong>cuánto trabajo cuesta</strong> —lo fija el protocolo— y <strong>cuánto se paga por unidad de trabajo</strong> —lo fija la demanda—.</p></li><li><p><strong>Leer es barato, escribir es caro, y ocupar una casilla nueva es lo más caro</strong>, porque todos tendrán que guardarla.</p></li><li><p>Consultar el estado <strong>no cuesta ni se firma</strong>. Solo se paga lo que cambia el estado.</p></li><li><p>Si el trabajo se agota, <strong>el estado vuelve atrás y se paga igual</strong>. Si fuera gratis, atacar la red sería gratis.</p></li><li><p>El coste <strong>no depende de cuánto mueves</strong>: es un peaje fijo. Por eso una red cara <strong>no se encarece para todos, deja fuera a los de abajo</strong>.</p></li><li><p>Abaratar la ejecución se paga en que <strong>menos gente pueda mantener una copia</strong>. La tensión no tiene salida, solo puntos donde quedarse.</p></li></ul><hr><h3>➡️ Qué viene después</h3><p>Ya sabes qué cuesta ejecutar y por qué. Queda el otro límite, y es más profundo que el precio: <strong>hay cosas que un programa de estos no puede hacer por diseño</strong>, no porque sea caro. No puede saber qué hora es, no puede mirar fuera y no puede sacar un número al azar. La lección siguiente explica por qué, y quién acaba metiendo el mundo exterior dentro.</p>')
ON CONFLICT (id) DO NOTHING;

-- 1.3 lo-que-un-contrato-no-puede-hacer (8163 car)
INSERT INTO public.lessons (id, course_id, module_id, title, slug, description, order_index, content)
VALUES ('ad91ed56-57d8-4fec-9b29-7115e4baddaa', 'd6f814e2-26d6-4d72-8e01-ce224fcde3f5', '3b2cb791-1ebd-4490-ad11-28f420361e2a', 'Lo que un contrato no puede hacer', 'lo-que-un-contrato-no-puede-hacer', 'No sabe la hora, no puede mirar fuera y no puede sacar un número al azar. Quién acaba metiendo el mundo exterior dentro, y cómo falla.', 2, '<h3>🎯 Objetivo de la lección</h3><p>Entender el límite que no es de precio: hay cosas que un programa de estos no puede hacer por diseño. No sabe qué hora es, no puede mirar fuera y no puede sacar un número al azar. De ahí sale la pieza que explica la mayoría de los fallos caros del ecosistema: <strong>alguien tiene que meter el mundo exterior dentro</strong>.</p><hr><h3>🧮 Una máquina muy limitada, a propósito</h3><p>Los programas no se ejecutan en el ordenador de nadie en particular. Se ejecutan en una <strong>máquina virtual</strong>: un procesador imaginario, definido en el protocolo, que todos los que mantienen una copia reproducen exactamente igual.</p><p>«Exactamente igual» es la clave, y viene directamente de lo que ya sabes de <em>Blockchain</em>: si todos ejecutan lo mismo y comparan el resultado, <strong>el resultado tiene que ser el mismo para todos, siempre</strong>. Da igual el ordenador, el país, el momento en que lo ejecute o el sistema operativo.</p><p>A eso se le llama que la ejecución sea <strong>determinista</strong>: las mismas entradas dan la misma salida, sin excepciones. Y esa exigencia, que parece inocente, prohíbe un montón de cosas que cualquier programa normal hace sin pensar.</p><hr><h3>🚫 Cuatro cosas que no puede hacer</h3><p><strong>1. No puede consultar nada de fuera.</strong> No puede pedir una página web, ni llamar a un servicio, ni leer un archivo. Si pudiera, dos copias que preguntaran en momentos distintos obtendrían respuestas distintas y dejarían de coincidir.</p><p><strong>2. No sabe qué hora es.</strong> Lo único parecido a un reloj es la hora que declara el bloque en el que se ejecuta, que la pone quien construye el bloque y tiene margen. Sirve para «después del día tal», no para nada fino.</p><p><strong>3. No puede sacar un número al azar.</strong> El azar de verdad es lo contrario del determinismo. Todo lo que parezca aleatorio sale de datos del propio registro, y <strong>quien construye el bloque tiene influencia sobre esos datos</strong>. Es un problema real: cualquier reparto que dependa de un azar mal construido es manipulable por quien ordena las operaciones.</p><p><strong>4. No puede actuar solo.</strong> Ya lo viste en la 1.1: no vigila y no se despierta. Alguien de fuera tiene que llamarlo y pagar.</p><p>Y todo esto <strong>no es una carencia que se vaya a arreglar</strong>. Es el precio de que cualquiera pueda comprobar el resultado sin fiarse de quien lo produjo. La pregunta de siempre: a cambio de eso, el programa se queda ciego y quieto.</p><hr><h3>🌐 Entonces, ¿cómo sabe un contrato cuánto vale algo?</h3><p>No lo sabe. <strong>Alguien se lo escribe.</strong></p><p>Esa es la respuesta completa, y conviene que quede desnuda, porque el nombre técnico —<em>oráculo</em>— suena a mecanismo y no lo es. Un oráculo es <strong>una parte que anota dentro del registro un dato de fuera</strong>. Nada más. El contrato lee esa anotación y la da por buena, porque no tiene forma de comprobarla.</p><p>Con eso se sostienen la mayoría de las cosas que hacen estas redes: cualquier programa que dependa de un precio, de un resultado, de una temperatura o de si algo ocurrió, <strong>depende de quien escribe ese dato</strong>.</p><p>Y de ahí la consecuencia incómoda: se puede tener un contrato perfectamente escrito, verificado y revisado, que se comporte de forma catastrófica <strong>sin que su código tenga ningún fallo</strong>, porque el dato del que dependía era falso. El programa hizo exactamente lo que decía.</p><hr><h3>💣 Las tres formas de que el dato falle</h3><p>Ordenadas de la más obvia a la que más dinero se ha llevado.</p><p><strong>1. Quien lo escribe miente o le fuerzan a mentir.</strong> Si una sola parte escribe el dato, esa parte puede vaciar todo lo que dependa de él. Es la versión directa, y por eso casi nadie la deja así.</p><p><strong>2. El dato es correcto pero viejo.</strong> Escribir cuesta, así que los datos no se actualizan continuamente: se actualizan cuando cambian lo suficiente o cuando pasa cierto tiempo. En un momento de movimiento brusco, <strong>el contrato opera con una realidad de hace un rato</strong>. Nadie ha mentido y el resultado es igual de malo.</p><p><strong>3. El dato es cierto, y el problema es lo que mide.</strong> Esta es la fina. Si el dato refleja el precio de un mercado pequeño, alguien con suficiente dinero puede <strong>mover ese mercado a propósito durante unos segundos</strong>, hacer que el contrato valore algo mal y aprovecharlo. El oráculo hizo su trabajo con honradez: informó de un precio que era real. Manipular la realidad es más barato que manipular el informe.</p><p>La tercera es la que hay que entender, porque desmonta la idea tranquilizadora de «el dato viene de varias fuentes independientes». Varias fuentes independientes que miran el mismo mercado delgado <strong>coinciden todas en el precio manipulado</strong>.</p><hr><h3>🎲 El caso del azar, en una frase</h3><p>Merece su apartado porque se repite en repartos, sorteos y adjudicaciones. Si el número «al azar» sale de algo del registro —la huella de un bloque, la hora, el saldo de una cuenta—, <strong>quien construye el bloque puede elegir entre varios resultados posibles</strong>, o simplemente no incluir la operación si no le conviene.</p><p>No hace falta un ataque sofisticado: basta con estar en la posición de ordenar las operaciones. Es la misma ventaja que ya conoces de <em>Blockchain</em>: <strong>quien decide el orden tiene ventaja</strong>, aquí aplicada a un sorteo.</p><hr><h3>🧭 Qué preguntar cuando algo depende de un dato de fuera</h3><p>Cinco preguntas. Ninguna exige leer código.</p><ol><li><p><strong>¿Quién puede escribir este dato?</strong> Una parte, varias, o cualquiera que aporte algo a cambio.</p></li><li><p><strong>¿De dónde sale, y qué profundidad tiene lo que mide?</strong> Un dato sacado de un sitio donde mueve poco dinero es manipulable, por muchas fuentes que lo confirmen.</p></li><li><p><strong>¿Cada cuánto se actualiza, y qué pasa si deja de llegar?</strong> Lo segundo importa más: hay contratos que se paran y contratos que siguen con el último valor que tenían.</p></li><li><p><strong>¿El contrato distingue un dato fresco de uno viejo?</strong> Si no comprueba la antigüedad, un dato caducado le vale igual.</p></li><li><p><strong>¿Qué pasa si el dato es absurdo?</strong> Un buen diseño se detiene ante un valor imposible. Uno malo lo ejecuta.</p></li></ol><p>Y si alguna no tiene respuesta pública, <strong>eso ya es la respuesta</strong>. La regla es la misma de <em>Blockchain</em>, y aquí se aplica igual.</p><hr><h3>📌 En resumen</h3><ul><li><p>Los programas corren en una <strong>máquina virtual</strong> que todos reproducen igual, así que la ejecución tiene que ser <strong>determinista</strong>: mismas entradas, misma salida, siempre.</p></li><li><p>Por eso un contrato <strong>no puede consultar nada de fuera, no sabe qué hora es, no puede sacar un número al azar y no puede actuar solo</strong>.</p></li><li><p>No es una carencia por resolver: es <strong>el precio de que cualquiera pueda comprobar el resultado</strong>.</p></li><li><p>Un <strong>oráculo</strong> no es un mecanismo: es <strong>alguien que escribe un dato de fuera dentro del registro</strong>, y el contrato lo da por bueno porque no puede comprobarlo.</p></li><li><p>Un contrato sin ningún fallo puede comportarse de forma catastrófica <strong>si el dato del que dependía era falso</strong>.</p></li><li><p>El dato falla de tres formas: <strong>alguien miente</strong>, <strong>es correcto pero viejo</strong> o <strong>es cierto y mide algo manipulable</strong>. La tercera desmonta el consuelo de «viene de varias fuentes».</p></li><li><p>Si el azar sale del propio registro, <strong>quien construye el bloque influye en el resultado</strong>.</p></li></ul><hr><h3>➡️ Qué viene después</h3><p>Con esto cierra el módulo: ya sabes qué añadió esta red, qué cuesta y qué no puede hacer. El módulo 2 va a lo que de verdad decide si algo sale mal, y empieza por lo más elemental y lo que menos gente comprueba: <strong>que el código que lees no es necesariamente el que se ejecuta</strong>.</p>')
ON CONFLICT (id) DO NOTHING;

-- 2.1 de-donde-sale-el-codigo-que-se-ejecuta (7983 car)
INSERT INTO public.lessons (id, course_id, module_id, title, slug, description, order_index, content)
VALUES ('121e2b02-c063-4471-b205-5a597799453a', 'd6f814e2-26d6-4d72-8e01-ce224fcde3f5', 'f9e7695b-5f04-47f7-9ae9-f468676a4dc0', 'De dónde sale el código que se ejecuta', 'de-donde-sale-el-codigo-que-se-ejecuta', 'El código que corre, el que puedes leer y que alguien lo haya revisado son tres cosas distintas. Cuál puedes comprobar tú sin programar.', 0, '<h3>🎯 Objetivo de la lección</h3><p>Separar tres cosas que se confunden todo el tiempo: <strong>el código que se ejecuta</strong>, <strong>el código que puedes leer</strong> y <strong>que alguien lo haya revisado</strong>. Son independientes, y de las tres hay una que puedes comprobar tú sin saber programar.</p><hr><h3>🧱 Lo que hay realmente en esa dirección</h3><p>Cuando alguien publica un contrato, lo que queda en el registro <strong>no es el texto que escribió</strong>. Es el resultado de traducirlo a instrucciones que entiende la máquina virtual: una tira de datos ilegible para una persona.</p><p>Eso es lo único que la red ejecuta. La red <strong>no ha visto nunca el texto original</strong> y no lo necesita.</p><p>El texto legible, si existe, está en otro sitio: en un repositorio, en una web, en un explorador. <strong>Fuera del registro.</strong> Y ahí está el hueco de la lección: lo que tú lees y lo que se ejecuta llegaron por caminos distintos, y nada garantiza por sí mismo que se correspondan.</p><hr><h3>🔗 Qué significa «código verificado»</h3><p>Hay una comprobación que cierra ese hueco, y es la que merece la pena buscar.</p><p>Consiste en <strong>traducir otra vez el texto publicado y comparar el resultado con lo que hay en el registro</strong>. Si coincide, el texto legible es el que se ejecuta. Si no coincide, el texto no describe lo que hay ahí.</p><p>Dos cosas importantes sobre esa comprobación:</p><ul><li><p><strong>No la hace el protocolo.</strong> La hacen servicios de consulta, fuera de la red. Así que te fías de que ese servicio la hizo bien.</p></li><li><p><strong>Pero cualquiera puede repetirla.</strong> Y eso la distingue de una promesa: es una comprobación reproducible, no una declaración.</p></li></ul><p>De ahí salen tres situaciones distintas, y conviene saber en cuál estás:</p><ol><li><p><strong>No hay texto publicado.</strong> Solo la tira de datos. Nadie de fuera puede saber qué hace sin un trabajo considerable. Para cualquier uso corriente, es una caja cerrada.</p></li><li><p><strong>Hay texto publicado, pero no verificado.</strong> Es lo peor de los tres, porque parece transparencia. El texto puede ser una versión anterior, una versión parecida o algo que no tiene nada que ver.</p></li><li><p><strong>Hay texto publicado y verificado.</strong> Lo que lees es lo que se ejecuta.</p></li></ol><p>La tercera no significa que sea bueno. <strong>Significa que es legible.</strong> Que ya es bastante más de lo que parece.</p><hr><h3>🔍 Qué es una auditoría, y qué no</h3><p>La otra palabra que se usa como sello de calidad. Vale la pena desmontarla, sin desdén: una revisión seria hecha por gente competente es valiosa, y no tenerla es peor.</p><p>Lo que es: <strong>unas personas leyeron una versión concreta del código durante un tiempo concreto, buscando ciertos tipos de fallo, y publicaron lo que encontraron.</strong> Eso es todo, y es mucho.</p><p>Lo que no es:</p><ul><li><p><strong>No es una garantía de que no haya fallos.</strong> Nadie puede demostrar eso. Se ha auditado código que después falló.</p></li><li><p><strong>No cubre el código que se ejecuta hoy</strong>, necesariamente. Cubre la versión que revisaron. Si el contrato se puede cambiar —la lección siguiente—, lo que corre ahora puede no ser lo auditado.</p></li><li><p><strong>No es una responsabilidad.</strong> Quien audita no responde de tus pérdidas; su informe suele decirlo explícitamente.</p></li><li><p><strong>No cubre lo que quedó fuera del alcance.</strong> Y lo que queda fuera suele ser lo interesante: los oráculos, los permisos de administración, lo que pasa cuando el contrato llama a otro que no auditaron.</p></li></ul><hr><h3>🧾 Cómo se lee una auditoría sin ser técnico</h3><p>No hay que entender los hallazgos. Hay que mirar cuatro datos de la portada, y con eso se distingue un informe de un adorno:</p><ol><li><p><strong>La fecha y la versión exacta revisada.</strong> Si no dice qué versión, no dice nada.</p></li><li><p><strong>El alcance.</strong> Qué se revisó y, sobre todo, qué se excluyó.</p></li><li><p><strong>Los hallazgos y qué se hizo con ellos.</strong> Un informe con fallos graves <em>corregidos y vueltos a revisar</em> es mejor señal que uno sin hallazgos.</p></li><li><p><strong>Que exista el documento.</strong> Un sello, un logotipo o la frase «auditado por» sin informe descargable no es una auditoría. Es una afirmación.</p></li></ol><p>Y una comprobación que remata: <strong>¿la versión que revisaron es la que está funcionando?</strong> Es la pregunta que casi nadie hace y la que más veces se cae.</p><hr><h3>🧩 Tres cosas distintas que se usan como sinónimos</h3><p>Conviene separarlas del todo, porque cada una dice algo diferente:</p><ul><li><p><strong>Código abierto</strong> significa que hay texto publicado y una licencia. No dice que coincida con lo que se ejecuta.</p></li><li><p><strong>Código verificado</strong> significa que coincide con lo que se ejecuta. No dice que sea bueno.</p></li><li><p><strong>Código auditado</strong> significa que alguien lo leyó. No dice que no falle, ni que sea la versión actual.</p></li></ul><p>Las tres pueden faltar por separado, y hay proyectos que tienen la primera y presumen de las otras dos.</p><hr><h3>⚖️ Lo que puedes hacer y lo que no</h3><p>Conviene ser honesto con el límite, en la línea del resto de los cursos.</p><p><strong>Leer código y detectar un fallo no está a tu alcance</strong>, ni al de la mayoría de los que lo intentan. No se arregla con un curso, y desconfía de quien te sugiera que sí.</p><p>Lo que sí está a tu alcance, y no exige saber programar, son cuatro hechos:</p><ol><li><p><strong>Si hay texto publicado y si está verificado.</strong> Es un dato que se consulta y se ve a simple vista.</p></li><li><p><strong>Si existe un informe de revisión, con fecha y versión.</strong></p></li><li><p><strong>Si la versión revisada es la que se ejecuta.</strong></p></li><li><p><strong>Quién puede cambiarlo.</strong> Que es la lección siguiente, y es la que más pesa de las cuatro.</p></li></ol><p>Cuatro respuestas comprobables valen más que una lectura superficial del código, y son alcanzables. <strong>El objetivo no es auditar: es saber en qué situación estás.</strong></p><hr><h3>📌 En resumen</h3><ul><li><p>En el registro no hay texto legible: hay <strong>instrucciones para la máquina virtual</strong>. La red nunca ha visto el código original.</p></li><li><p>El texto legible vive <strong>fuera del registro</strong>, así que lo que lees y lo que se ejecuta llegaron por caminos distintos.</p></li><li><p><strong>«Verificado»</strong> significa que alguien tradujo otra vez el texto publicado y coincide con lo que hay dentro. No lo hace el protocolo, pero <strong>cualquiera puede repetirlo</strong>.</p></li><li><p>Tres situaciones: <strong>sin texto</strong> (caja cerrada), <strong>con texto sin verificar</strong> (la peor, porque parece transparencia) y <strong>verificado</strong> (legible, no necesariamente bueno).</p></li><li><p>Una auditoría es <strong>gente que leyó una versión concreta buscando ciertos fallos</strong>. No garantiza que no haya fallos, no cubre lo excluido, no es una responsabilidad y <strong>puede no cubrir lo que corre hoy</strong>.</p></li><li><p>Sin informe descargable con fecha y versión, «auditado» es <strong>una afirmación, no una auditoría</strong>.</p></li><li><p><strong>Abierto, verificado y auditado son tres cosas distintas</strong>, y se usan como si fueran una.</p></li><li><p>No puedes auditar, y no hace falta: puedes comprobar <strong>cuatro hechos</strong>, y el que más pesa es quién puede cambiarlo.</p></li></ul><hr><h3>➡️ Qué viene después</h3><p>Ya sabes leer la etiqueta. Queda la pregunta que <em>Qué es Web3 y qué no</em> te enseñó a hacer y no a responder, y que aquí aparece por cuarta vez: <strong>¿quién puede cambiar esto después de que lo hayas revisado, y qué hace falta para que lo cambie?</strong> La lección siguiente la responde entera.</p>')
ON CONFLICT (id) DO NOTHING;

-- 2.2 quien-puede-cambiar-las-reglas (7745 car)
INSERT INTO public.lessons (id, course_id, module_id, title, slug, description, order_index, content)
VALUES ('c1a156bc-1a9d-4266-bc93-56f862eb7a1e', 'd6f814e2-26d6-4d72-8e01-ce224fcde3f5', 'f9e7695b-5f04-47f7-9ae9-f468676a4dc0', 'Quién puede cambiar las reglas después', 'quien-puede-cambiar-las-reglas', 'Cómo se cambia algo inmutable, la escala de quién aprieta el interruptor, y por qué los dos extremos tienen precio.', 1, '<h3>🎯 Objetivo de la lección</h3><p>Responder de una vez la pregunta que arrastras desde <em>Qué es Web3 y qué no</em>: <strong>¿quién puede cambiar un contrato y qué hace falta para que lo haga?</strong> Cómo se cambia algo que se supone inmutable, qué poderes existen además de cambiar el código, y cómo se responde la pregunta sin saber programar.</p><hr><h3>🪤 La trampa: el código no cambia, el comportamiento sí</h3><p>Las dos frases que se repiten son ciertas y engañan juntas:</p><p><strong>«El código de un contrato no se puede modificar.»</strong> Cierto. Las instrucciones que hay en una dirección son las que son para siempre.</p><p><strong>«Este proyecto ha actualizado su contrato.»</strong> También cierto, y pasa todos los días.</p><p>No hay contradicción, porque <strong>se cambia sin modificar nada</strong>. El truco es viejo y sencillo: la dirección con la que tú tratas <em>no contiene la lógica</em>. Contiene una nota que dice «lo que hay que ejecutar está en esa otra dirección» y reenvía las llamadas allí.</p><p>Esa nota se puede reescribir. <strong>Se publica un contrato nuevo en otra dirección y se cambia la nota para que apunte a él.</strong> La dirección que tú conoces no ha cambiado, tu saldo sigue ahí, y sin embargo las reglas que lo gobiernan son otras desde hace un bloque.</p><p>Es la pieza que hay que entender de esta lección: <strong>la inmutabilidad protege el código, no protege tus condiciones</strong>.</p><hr><h3>🔑 Quién aprieta el interruptor</h3><p>Ese cambio no lo puede hacer cualquiera. Lo hace quien tenga el permiso, y ahí hay una escala real, de menos a más garantía para ti:</p><p><strong>1. Una sola clave.</strong> Una persona, o quien le haya robado la clave, cambia las reglas en el tiempo que tarda una operación. Es la situación más común en proyectos recientes y la que menos se anuncia.</p><p><strong>2. Varias claves, y hacen falta unas cuantas.</strong> Tres de cinco, cuatro de siete. Mejor, con dos advertencias: hay que saber <strong>si las claves son de personas distintas o del mismo equipo</strong> —porque cinco claves en un cajón son una clave— y si la lista está publicada.</p><p><strong>3. Varias claves y además una demora.</strong> El cambio se anuncia y no puede aplicarse hasta que pasa un plazo. Esto es lo que de verdad te protege, y no porque impida el cambio: <strong>porque te da tiempo a irte</strong>. Es la diferencia entre enterarte antes y enterarte después.</p><p><strong>4. Una votación.</strong> Puede ser mejor o mucho peor que las anteriores, y depende de quién tenga los votos. Si unos pocos concentran la mayoría, es el punto 1 con un trámite. Se mira en el reparto, no en el reglamento.</p><p><strong>5. Ningún mecanismo.</strong> No se puede cambiar. Nadie, nunca.</p><hr><h3>⚖️ Y aquí no hay una respuesta buena</h3><p>Lo cómodo sería decir que el punto 5 es el ideal. No lo es, y esta es la parte honesta de la lección.</p><p><strong>Un contrato que no se puede cambiar tampoco se puede arreglar.</strong> Si tiene un fallo, el fallo es permanente, y lo único que se puede hacer es avisar a la gente de que salga. Cosa que ha pasado.</p><p>Así que los dos extremos tienen precio:</p><ul><li><p><strong>Poder cambiarlo</strong> se paga en que existe alguien con la llave, y su decisión, su error o su coacción son tu riesgo.</p></li><li><p><strong>No poder cambiarlo</strong> se paga en que un fallo no tiene arreglo y una circunstancia nueva no se puede acomodar.</p></li></ul><p>La pregunta de siempre, otra vez: <strong>¿a cambio de qué?</strong> Y la conclusión práctica no es «busca contratos inmutables», sino <strong>saber en qué punto de la escala estás y que sea el que crees</strong>.</p><p>Con una afirmación que sí conviene dejar clara: <strong>un contrato que alguien puede cambiar a su gusto y sin demora es un servicio gestionado por ese alguien, con pasos de más.</strong> Puede estar perfectamente bien usarlo. Lo que no está bien es creer que no dependes de nadie.</p><hr><h3>🎚️ Los otros poderes, que se cuentan menos</h3><p>Cambiar la lógica es el poder grande, pero hay otros que no requieren cambiar nada y bastan para arruinarte el día. Conviene conocerlos por nombre porque aparecen en los contratos continuamente:</p><ul><li><p><strong>Pausar.</strong> Detener el contrato. Nadie puede operar, <em>ni sacar</em>. A veces es una protección sensata ante un ataque; a veces es una puerta cerrada con tu dinero dentro.</p></li><li><p><strong>Cambiar un parámetro.</strong> Una comisión, un límite, un plazo, un umbral. Sin tocar el código: el código ya preveía que ese número fuera modificable.</p></li><li><p><strong>Añadir o quitar direcciones de una lista.</strong> Permitir o impedir que ciertas cuentas operen. En la lección 3.2 verás la versión más fuerte de esto.</p></li><li><p><strong>Retirar fondos por una vía de emergencia.</strong> Una función pensada para rescatar en caso de desastre, que es exactamente la misma función que se necesita para vaciarlo.</p></li></ul><p>Un contrato puede ser inmutable y tener las cuatro. <strong>«Inmutable» no significa «sin dueño».</strong></p><hr><h3>🧭 Cómo se responde la pregunta, en la práctica</h3><p>Cuatro comprobaciones. Ninguna exige leer código, y las cuatro son datos públicos:</p><ol><li><p><strong>¿La dirección reenvía a otra?</strong> Es decir, ¿el comportamiento puede cambiar? Es un hecho consultable, y es el primero.</p></li><li><p><strong>¿Quién tiene el permiso y está publicado quién es?</strong> Una clave, varias, un voto. Y si son varias: ¿de gente distinta?</p></li><li><p><strong>¿Hay demora, y cuánta?</strong> Sin demora, la garantía es la buena voluntad del que tiene la llave.</p></li><li><p><strong>¿Hay registro de los cambios anteriores?</strong> Un historial de cambios silenciosos dice más que cualquier documento.</p></li></ol><p>Y la regla que ya conoces: <strong>si alguna no tiene respuesta pública, eso ya es la respuesta</strong>. No es una sospecha, es una descripción: estás en un sistema cuyas reglas puede cambiar alguien que no has identificado.</p><hr><h3>📌 En resumen</h3><ul><li><p><strong>El código no se modifica; el comportamiento sí.</strong> Se publica lógica nueva en otra dirección y se reescribe la nota que dice dónde está.</p></li><li><p>Así que <strong>la inmutabilidad protege el código, no tus condiciones</strong>.</p></li><li><p>La escala, de menos a más garantía: <strong>una clave</strong>, <strong>varias claves</strong>, <strong>varias claves con demora</strong>, <strong>una votación</strong> —que vale lo que valga el reparto de votos— y <strong>ningún mecanismo</strong>.</p></li><li><p>La demora es lo que de verdad protege, y no porque impida el cambio: <strong>porque te da tiempo a irte</strong>.</p></li><li><p>No poder cambiar nada <strong>también tiene precio</strong>: un fallo es permanente. Los dos extremos cuestan algo.</p></li><li><p><strong>Un contrato que alguien cambia a su gusto y sin demora es un servicio gestionado por ese alguien</strong>, con pasos de más.</p></li><li><p>Hay poderes que no cambian el código y bastan: <strong>pausar, cambiar un parámetro, listas de direcciones y la vía de emergencia</strong>. «Inmutable» no significa «sin dueño».</p></li><li><p>Cuatro comprobaciones públicas: <strong>si reenvía, quién tiene el permiso, si hay demora y si hay historial</strong>.</p></li></ul><hr><h3>➡️ Qué viene después</h3><p>Ya tienes las dos primeras piezas de por qué algo sale mal: el código puede no ser el que crees, y las reglas puede cambiarlas alguien. La lección siguiente cierra el módulo juntándolas con las otras dos y poniéndoles orden: <strong>las cuatro formas por las que el dinero sale de un contrato</strong>, y cuál de ellas depende solo de ti.</p>')
ON CONFLICT (id) DO NOTHING;

-- 2.3 las-cuatro-formas-de-perder-los-fondos (8775 car)
INSERT INTO public.lessons (id, course_id, module_id, title, slug, description, order_index, content)
VALUES ('97e07ef4-aafb-4665-841e-ba0e9d7d866b', 'd6f814e2-26d6-4d72-8e01-ce224fcde3f5', 'f9e7695b-5f04-47f7-9ae9-f468676a4dc0', 'Las cuatro formas de que el dinero salga de un contrato', 'las-cuatro-formas-de-perder-los-fondos', 'Un orden imprevisto, un dato de fuera, alguien con permiso y tu propia firma. Dos son fallos; los otros dos, el diseño funcionando.', 2, '<h3>🎯 Objetivo de la lección</h3><p>Poner orden en el desastre. Hay muchas maneras de perder dinero aquí, pero <strong>solo hay cuatro caminos por los que sale de un contrato</strong>. Conocerlos por separado sirve para saber, ante cualquier cosa, de cuál de los cuatro dependes y cuál está en tu mano.</p><hr><h3>🗺️ Los cuatro caminos</h3><p>Dicho de golpe, y después uno por uno:</p><ol><li><p><strong>El contrato hizo lo que decía, en un orden que nadie previó.</strong></p></li><li><p><strong>El contrato creyó un dato de fuera que no era el que parecía.</strong></p></li><li><p><strong>Alguien con permiso lo usó.</strong></p></li><li><p><strong>Lo firmaste tú.</strong></p></li></ol><p>Los dos primeros son fallos. Los dos últimos <strong>no son fallos de nada</strong>: son el sistema funcionando como está diseñado. Y esa distinción es más importante que la lista, porque cambia por completo lo que puedes hacer al respecto.</p><hr><h3>1️⃣ El orden que nadie previó</h3><p>El caso escolar es este. Un contrato tiene que devolverte tu depósito, y hace dos cosas: te manda el dinero y después apunta que ya no tienes nada.</p><p>Parece correcto. Pero mandar dinero a una cuenta que es un programa <strong>ejecuta ese programa</strong>. Y si ese programa, al recibir, vuelve a pedir su depósito, entra otra vez en el contrato <em>antes de que este haya apuntado que ya pagó</em>. La casilla todavía dice que le debe. Así que le paga otra vez. Y otra.</p><p>El nombre técnico es <strong>reentrada</strong>, y el patrón general es lo que interesa: <strong>el contrato dio por supuesto que nada pasaría entre dos de sus propios pasos</strong>. Como aquí una llamada puede devolver el control a quien la hizo, ese supuesto es falso.</p><p>Es la familia de fallos más conocida y no la única: cualquier sitio donde un contrato supone que el mundo se queda quieto mientras él trabaja pertenece a esta categoría.</p><p><strong>Y tiene el precedente más caro de la historia de esta red.</strong> En 2016 un contrato con este fallo fue vaciado, y la respuesta fue tan extraordinaria que conviene recordarla: se cambió la propia cadena para deshacerlo, y la red acabó <strong>partida en dos</strong>, porque una parte de los participantes no aceptó que las reglas se tocaran ni para eso. Es la única vez que la respuesta a un fallo de un contrato fue reescribir el registro, y explica por qué la discusión sobre quién puede cambiar las reglas —la lección anterior— no es teórica.</p><hr><h3>2️⃣ El dato de fuera</h3><p>Ya lo tienes de la 1.3, así que basta con situarlo: el contrato no puede comprobar nada del mundo, alguien se lo escribe, y si lo que le escriben no es lo que parece, <strong>el contrato ejecuta con obediencia un resultado desastroso sin tener ningún fallo</strong>.</p><p>Lo que hay que recordar de esa lección es la tercera forma, la fina: no hace falta que nadie mienta. Basta con <strong>mover a propósito el mercado que el dato mide</strong> para que el contrato valore algo mal durante unos segundos.</p><p>Es el camino que menos se anticipa, porque todo el mundo revisa el contrato y casi nadie revisa <em>de qué se fía</em> el contrato.</p><hr><h3>3️⃣ Alguien con permiso</h3><p>Aquí no hay fallo, no hay ataque y no hay nada roto. Está en la lección anterior: quien puede cambiar la lógica, pausar, mover un parámetro o usar la vía de emergencia <strong>hace lo que el contrato le permite hacer</strong>.</p><p>Vale la pena separar dos casos que se cuentan como uno:</p><ul><li><p><strong>Lo usa quien debe, y sale mal.</strong> Un equipo pausa, o cambia algo, o rescata fondos, y su decisión te perjudica. No es un delito: es que dependías de su criterio.</p></li><li><p><strong>Lo usa quien no debe.</strong> A alguien le roban la clave, o le engañan, o le obligan. El permiso funciona exactamente igual, porque el contrato no distingue quién firma: comprueba que la firma es válida.</p></li></ul><p>Y de ahí la frase de la lección anterior, que aquí se ve para qué servía: <strong>si alguien puede cambiarlo sin demora, tu riesgo incluye a esa persona entera</strong>, con sus decisiones, sus errores y su seguridad personal.</p><hr><h3>4️⃣ Lo firmaste tú</h3><p>El cuarto camino es el que no requiere que nada falle, y es el único que depende solo de ti. Tres formas, y las tres son la misma cosa vista de tres maneras:</p><ul><li><p><strong>Autorizaste sin límite.</strong> De <em>Qué es Web3 y qué no</em>: una firma que concede a un contrato permiso para mover tus fondos cuando quiera, normalmente sin tope y sin caducidad. Meses después ese contrato cambia —lección anterior— o alguien encuentra cómo usarlo, y el permiso sigue vivo.</p></li><li><p><strong>Firmaste una cosa creyendo que era otra.</strong> Lo que lees en pantalla lo escribió una web; lo que firmas son datos. Si las dos cosas no coinciden, no hay nada en el sistema que lo impida.</p></li><li><p><strong>Firmaste en el sitio equivocado.</strong> Una copia de la interfaz que esperabas. El contrato al que llamas es otro, y hace exactamente lo que dice hacer.</p></li></ul><p>En los tres casos <strong>el sistema funcionó perfectamente</strong>. Tu firma era válida, la operación era legítima y no hay nada que revertir. La lección 3.1 entra en esto de lleno.</p><p>No hay cifras públicas fiables de cuánto se pierde por cada camino, y no vamos a inventarlas. Sí se puede decir algo comprobable: <strong>los dos primeros caminos exigen un atacante con conocimientos; el cuarto, solo un despiste.</strong></p><hr><h3>🛡️ De qué te puedes defender, honestamente</h3><p>Puestos en fila, no están a la misma distancia de ti:</p><ul><li><p><strong>Caminos 1 y 2: no puedes evaluarlos.</strong> Requieren leer código y entender de qué se fía el contrato. Lo único que tienes es indirecto: si el código está verificado, si hay una revisión seria de la versión que corre, y cuánto tiempo lleva funcionando con dinero dentro sin romperse.</p></li><li><p><strong>Camino 3: sí puedes comprobarlo.</strong> Son las cuatro comprobaciones de la lección anterior, y son datos públicos. Este es el que más gente se salta pudiendo no saltárselo.</p></li><li><p><strong>Camino 4: es enteramente tuyo.</strong> No depende de la calidad de nada. Es el único que puedes reducir casi a cero sin ayuda de nadie.</p></li></ul><p>Y el recordatorio que atraviesa todos los cursos: <strong>aquí no hay a quién reclamar</strong>. No hay reverso, no hay atención al cliente y no hay tribunal. Por eso todo el trabajo útil ocurre antes de firmar.</p><hr><h3>🚩 Dos señales que combinan mal</h3><p>Sin entrar a juzgar ningún proyecto, hay dos combinaciones que se explican solas con lo que ya sabes:</p><p><strong>Código sin verificar más permiso de cambio sin demora.</strong> No puedes leer lo que hace y puede dejar de hacerlo cuando alguien quiera. Es depositar en algo cuyo comportamiento presente y futuro son ambos desconocidos.</p><p><strong>Auditoría antigua más contrato actualizable.</strong> El informe describe una versión que puede no existir ya. La auditoría tranquiliza sobre algo que no es lo que estás usando.</p><hr><h3>📌 En resumen</h3><ul><li><p>Solo hay <strong>cuatro caminos</strong>: un <strong>orden imprevisto</strong>, un <strong>dato de fuera</strong>, <strong>alguien con permiso</strong> y <strong>tu firma</strong>.</p></li><li><p>Los dos primeros son fallos; los dos últimos son <strong>el sistema funcionando como está diseñado</strong>.</p></li><li><p><strong>Reentrada</strong>: el contrato supuso que nada pasaría entre dos de sus propios pasos. En 2016 costó el vaciado de un contrato y <strong>la red partida en dos</strong> al deshacerlo.</p></li><li><p>El dato de fuera falla sin que nadie mienta: <strong>basta con mover el mercado que mide</strong>.</p></li><li><p>El permiso no distingue quién firma, así que <strong>tu riesgo incluye la seguridad personal de quien tiene la llave</strong>.</p></li><li><p>Tu propia firma no requiere que nada falle: <strong>autorización sin límite, firmar una cosa creyendo otra, o firmar en el sitio equivocado</strong>.</p></li><li><p>Los dos primeros caminos <strong>no los puedes evaluar</strong>; el tercero <strong>sí</strong>, con datos públicos; el cuarto <strong>es enteramente tuyo</strong>.</p></li><li><p>Combinan mal: <strong>código sin verificar con cambio sin demora</strong>, y <strong>auditoría antigua con contrato actualizable</strong>.</p></li></ul><hr><h3>➡️ Qué viene después</h3><p>Cierra el módulo. El tercero baja a lo que te vas a encontrar de verdad, y empieza por el cuarto camino, que es el único enteramente tuyo: <strong>qué ocurre exactamente cuando firmas</strong>, por qué una operación se queda atascada bloqueando a las siguientes, y por qué el orden en que se ejecutan no lo decides tú.</p>')
ON CONFLICT (id) DO NOTHING;

-- 3.1 firmas-permisos-y-orden-de-las-operaciones (8618 car)
INSERT INTO public.lessons (id, course_id, module_id, title, slug, description, order_index, content)
VALUES ('51c13dc4-f3ea-4ac2-97fc-691a3cbc483d', 'd6f814e2-26d6-4d72-8e01-ce224fcde3f5', 'f1084f23-f381-4b10-96c2-6615dfb604ee', 'Firmas, permisos y el orden de tus operaciones', 'firmas-permisos-y-orden-de-las-operaciones', 'Por qué una operación atascada bloquea a las siguientes, por qué el orden no lo decides tú, y qué es un permiso que sigue vivo meses después.', 0, '<h3>🎯 Objetivo de la lección</h3><p>Entender qué ocurre exactamente cuando firmas: por qué tus operaciones van numeradas y una atascada bloquea a las siguientes, por qué el orden en que se ejecutan no lo decides tú, y qué es un permiso que sigue vivo meses después. Es el cuarto camino de la lección anterior, el único que depende solo de ti.</p><p>Una aclaración sobre lo que esta lección no hace: <strong>no explica cómo conectarse a nada ni cómo usar ninguna aplicación</strong>. Explica qué está pasando por debajo cuando te piden una firma, que es lo que no caduca.</p><hr><h3>🔢 Tus operaciones van numeradas</h3><p>En la lección 1.1 apareció el contador de la cuenta. Aquí se ve para qué sirve.</p><p>Cada operación que sale de tu cuenta lleva un número, y van en orden estricto: <strong>la número 8 no se ejecuta hasta que se haya ejecutado la 7</strong>. Sirve para que la misma orden firmada no pueda ejecutarse dos veces, que es imprescindible cuando la orden es pública.</p><p>Y tiene una consecuencia que desconcierta a todo el mundo la primera vez: <strong>si la 7 se queda atascada, las demás se quedan detrás</strong>, aunque no tengan nada que ver y aunque hayan ofrecido pagar más. No hay adelantamiento por la derecha.</p><hr><h3>⏳ Qué significa «atascada»</h3><p>Una operación firmada pasa por tres estados, y conviene no confundirlos:</p><ul><li><p><strong>Firmada y enviada.</strong> Existe, es pública, cualquiera puede verla, y <em>todavía no ha pasado nada</em>. No ha modificado el estado ni ha costado dinero.</p></li><li><p><strong>Incluida.</strong> Alguien la metió en un bloque y se ejecutó. Aquí ya pasó, para bien o para mal.</p></li><li><p><strong>Ni una cosa ni la otra.</strong> Está esperando porque lo que ofreció pagar se ha quedado por debajo de lo que la red cobra ahora. Puede esperar así mucho tiempo.</p></li></ul><p>Y aquí lo importante, que casi nadie cuenta bien: <strong>una operación enviada no se puede cancelar</strong>. No existe ese botón, y no por un descuido de diseño: está firmada y es pública, así que cualquiera puede incluirla. Lo único que se puede hacer es <strong>sustituirla</strong>, firmando otra operación con el mismo número y pagando más, de modo que entre esa y la primera deje de ser válida.</p><p>Dos consecuencias que vale la pena tener claras:</p><ul><li><p><strong>Sustituir no es gratis.</strong> Pagas por la operación que la sustituye.</p></li><li><p><strong>Mientras esté esperando, puede ejecutarse en cualquier momento.</strong> Una operación olvidada no es una operación muerta.</p></li></ul><hr><h3>👀 Esperas a la vista de todos</h3><p>Esta parte cambia cómo se ven muchas cosas. Mientras tu operación espera, <strong>es pública y legible</strong>: lo que vas a hacer, con qué contrato y por cuánto.</p><p>Y quien construye el bloque decide qué operaciones entran y <strong>en qué orden</strong>. Ya lo sabes de <em>Blockchain</em>: quien decide el orden tiene ventaja. Aquí se cobra esa ventaja.</p><p>La forma en que te afecta, sin tecnicismos: si tu operación tiene un resultado que depende de un precio, alguien puede colocar la suya justo antes, mover ese precio, dejar que la tuya se ejecute a un precio peor, y deshacer su posición justo después. <strong>Tu operación se ejecuta como pediste. Lo que recibes es menos de lo que viste en pantalla.</strong></p><p>De ahí que en cualquier operación de ese tipo aparezca <strong>un margen de tolerancia</strong>: hasta cuánto aceptas que el resultado se desvíe de lo previsto antes de que la operación falle en vez de ejecutarse. Y conviene entender las dos caras: <strong>un margen estrecho hace que la operación falle a menudo —y se paga igual—; un margen amplio autoriza por adelantado un resultado malo.</strong> No hay un número correcto; hay una decisión que estás tomando aunque no la mires.</p><p>Lo que no tiene remedio es la parte de fondo: <strong>no eliges el orden, y anunciar lo que vas a hacer antes de hacerlo es inevitable</strong> en un registro público.</p><hr><h3>✍️ Lo que te piden firmar</h3><p>De <em>Qué es Web3 y qué no</em> ya traes las tres clases de firma: un mensaje, una operación concreta y una <strong>autorización</strong>. La tercera es la que merece esta lección.</p><p>Una autorización es una casilla en el contrato de un token que dice: <em>esta otra dirección puede mover hasta tanto de lo que tiene esta cuenta</em>. Cuatro propiedades que hay que saber de memoria:</p><ul><li><p><strong>Es por contrato y por token.</strong> No es un permiso general, y por eso se acumulan muchas sin que te enteres.</p></li><li><p><strong>No caduca.</strong> Sigue ahí meses o años después, mientras no la quites.</p></li><li><p><strong>Suele pedirse sin tope.</strong> Es más cómodo para la aplicación: así no vuelve a molestarte.</p></li><li><p><strong>Quitarla es una operación</strong>, con su coste. No se deshace sola ni al dejar de usar el sitio.</p></li></ul><p>Y la combinación que ordena todo el curso: <strong>una autorización sin tope concedida a un contrato que alguien puede cambiar es una autorización concedida a lo que ese contrato llegue a ser</strong>. Tú aprobaste una cosa; el permiso vale para la siguiente.</p><hr><h3>🪤 La firma que no cuesta nada</h3><p>Hay firmas que no son operaciones: no se envían a la red, no cuestan y no aparecen en ningún sitio. Se firman y se entregan a quien te las pidió.</p><p>Suenan inofensivas justamente por eso —«no ha pasado nada, no he pagado nada»— y no lo son: <strong>una de esas firmas puede autorizar que otro mueva tus fondos después</strong>, o valer como una orden que alguien ejecutará cuando le convenga. El coste lo paga el que la usa, no el que la firma.</p><p>Es el punto ciego más útil de conocer de toda la lección: <strong>que algo sea gratis e invisible no significa que no autorice nada</strong>.</p><hr><h3>🧭 Lo que sí puedes hacer antes de firmar</h3><p>No es una lista de pasos, son cuatro preguntas. Y este camino, recuerda, es el único enteramente tuyo:</p><ol><li><p><strong>¿Esto lo he empezado yo?</strong> Una petición de firma que aparece sin que hayas pedido nada no se examina: se cierra.</p></li><li><p><strong>¿Es una operación o una autorización?</strong> Son cosas muy distintas, y la segunda sobrevive a la sesión.</p></li><li><p><strong>Si es una autorización, ¿tiene tope y a quién se la doy?</strong> Sin tope, estás firmando para siempre y para cualquier cantidad futura.</p></li><li><p><strong>¿El coste cuadra con lo que creo que estoy haciendo?</strong> De la lección 1.2: una operación sencilla que cuesta mucho está tocando más cosas de las que esperas.</p></li></ol><p>Y la frase con la que conviene quedarse: <strong>el único momento en que tienes todo el poder es antes de firmar</strong>. Después no hay reverso, no hay reclamación y no hay tribunal. Lo mismo que ya decía <em>Qué es Web3 y qué no</em>, dicho ahora sabiendo exactamente por qué.</p><hr><h3>📌 En resumen</h3><ul><li><p>Tus operaciones van <strong>numeradas y en orden estricto</strong>: si una se atasca, <strong>las siguientes esperan detrás</strong> aunque ofrezcan más.</p></li><li><p>Una operación enviada <strong>no se cancela</strong>: solo se <strong>sustituye</strong> por otra con el mismo número, pagando. Y mientras espera, puede ejecutarse en cualquier momento.</p></li><li><p>Mientras espera <strong>es pública</strong>, y quien construye el bloque elige el orden. Por eso puedes recibir <strong>menos de lo que viste en pantalla</strong> con una operación que se ejecutó tal como pediste.</p></li><li><p>El <strong>margen de tolerancia</strong> tiene dos caras: estrecho falla a menudo y se paga igual; amplio <strong>autoriza por adelantado un resultado malo</strong>.</p></li><li><p>Una <strong>autorización</strong> es por contrato y por token, <strong>no caduca</strong>, suele pedirse <strong>sin tope</strong>, y quitarla cuesta.</p></li><li><p>Sin tope y a un contrato que puede cambiar, <strong>autorizas lo que ese contrato llegue a ser</strong>.</p></li><li><p>Hay firmas <strong>gratis e invisibles que autorizan igual</strong>. Que no cueste no significa que no haga nada.</p></li><li><p>Cuatro preguntas: <strong>lo he empezado yo</strong>, <strong>operación o autorización</strong>, <strong>tope y beneficiario</strong>, <strong>el coste cuadra</strong>.</p></li></ul><hr><h3>➡️ Qué viene después</h3><p>La lección siguiente se ocupa de lo que más se usa de estas redes y menos se explica: <strong>las unidades que prometen valer siempre lo mismo</strong>. Qué sostiene esa promesa en cada caso, quién puede congelarlas y por qué no son un depósito.</p>')
ON CONFLICT (id) DO NOTHING;

-- 3.2 unidades-que-prometen-valer-un-euro (8970 car)
INSERT INTO public.lessons (id, course_id, module_id, title, slug, description, order_index, content)
VALUES ('3e2cd6f2-b69e-4346-ab91-b617f069045b', 'd6f814e2-26d6-4d72-8e01-ce224fcde3f5', 'f1084f23-f381-4b10-96c2-6615dfb604ee', 'Unidades que prometen valer un euro', 'unidades-que-prometen-valer-un-euro', 'Las tres formas de sostener esa promesa, quién puede congelarlas y por qué no son un depósito ni dinero al portador.', 1, '<h3>🎯 Objetivo de la lección</h3><p>Entender las unidades que prometen valer siempre lo mismo: qué sostiene esa promesa en cada diseño, quién puede congelarlas, por qué no son un depósito y qué habría que publicar para que fueran comprobables. Es lo que más se mueve en estas redes y lo que menos se explica.</p><hr><h3>🪙 Qué es exactamente</h3><p>Ya sabes lo que es un token: <em>una fila en la tabla de un contrato que dice que cierta dirección tiene cierta cantidad de algo</em>. Nada de eso cambia aquí.</p><p>Lo que cambia es la promesa que va encima: <strong>que cada unidad vale lo mismo que una unidad de algo de fuera del registro</strong> —un euro, un dólar—. Y lo importante es que <strong>eso no es una propiedad de la unidad</strong>. Es una promesa, y alguien o algo tiene que sostenerla.</p><p>Toda la lección consiste en mirar quién la sostiene, porque de ahí sale todo lo demás.</p><hr><h3>🏦 Forma 1: el respaldo está fuera del registro</h3><p>La más usada. Una entidad guarda dinero y activos en el mundo de fuera —cuentas bancarias, deuda a corto plazo—, emite unidades dentro del registro, y promete cambiártelas por dinero de verdad cuando se lo pidas.</p><p>El diseño es sencillo y funciona. Y hay que ver con claridad qué es:</p><p><strong>La promesa la hace una empresa, y el registro no puede comprobarla.</strong> Los contratos son ciegos a todo lo de fuera —lección 1.3—, así que ninguna propiedad de la cadena te dice si el respaldo existe. Lo único que hay dentro es el número de unidades emitidas. Lo de fuera es un asunto de confianza corriente, del mismo tipo que confiar en un banco, pero <strong>sin lo que suele acompañar a un banco</strong>.</p><p>Tres cosas que conviene tener claras de este diseño:</p><ul><li><p><strong>No es un depósito.</strong> No hay fondo de garantía. Si la entidad es insolvente, la pérdida es tuya y no hay a quién reclamar por encima de ella.</p></li><li><p><strong>Quien puede canjear no eres tú, normalmente.</strong> El canje directo suele estar reservado a clientes grandes con contrato. Tú dependes de que alguien te compre las unidades en un mercado, y eso es otra cosa: <strong>tienes el precio de mercado, no el derecho de canje</strong>.</p></li><li><p><strong>Qué respalda importa tanto como cuánto.</strong> Dinero en una cuenta y deuda a corto plazo no se comportan igual cuando todo el mundo quiere salir a la vez.</p></li></ul><hr><h3>❄️ El poder que casi nadie menciona: congelar</h3><p>Este es el apartado que justifica la lección, porque es lo que más contradice la idea que la gente tiene.</p><p>Los contratos de este tipo suelen incluir una capacidad documentada: <strong>impedir que una dirección concreta mueva sus unidades</strong>. A veces también anularlas y reemitirlas en otra dirección. Es la versión fuerte de las «listas de direcciones» de la lección 2.2.</p><p>No es un fallo, no es una puerta trasera oculta y no es una sospecha: <strong>está en el código y se ha usado</strong>. Existe porque la entidad emisora está sujeta a obligaciones legales, y cumplirlas exige poder hacerlo.</p><p>La consecuencia hay que decirla entera: <strong>estas unidades no son dinero al portador</strong>. Tener la clave no garantiza poder moverlas. Y eso las separa por completo del bitcoin y del ether, donde la única condición para gastar es tener la clave.</p><p>No es una razón para no usarlas. Es una razón para <strong>no confundir dos cosas distintas por el hecho de que vivan en el mismo registro</strong>.</p><hr><h3>🔒 Forma 2: el respaldo está dentro, y sobra</h3><p>El segundo diseño evita a la entidad: <strong>el respaldo está dentro del registro y lo custodia un contrato</strong>. Bloqueas más valor del que sacas —bastante más— y el contrato emite unidades contra ese depósito. Si el valor bloqueado baja demasiado, el contrato vende parte para cubrirse.</p><p>La ventaja es real y comprobable: <strong>cuánto hay bloqueado se puede ver</strong>, no hay que creerse a nadie, y no hay una empresa que pueda ser insolvente.</p><p>El precio también es real, y lo tienes todo en este curso:</p><ul><li><p><strong>Depende de un precio de fuera.</strong> Para saber si el depósito cubre, el contrato necesita saber cuánto vale lo depositado, y eso se lo escribe alguien. Todo lo de la lección 1.3 se aplica aquí, incluida la manipulación del mercado que el dato mide.</p></li><li><p><strong>Depende de que la venta forzosa funcione cuando hace falta.</strong> Y cuando hace falta es exactamente cuando todo baja a la vez, la red está cara y las operaciones se atascan. El diseño se pone a prueba en el peor momento por definición.</p></li><li><p><strong>Es ineficiente a propósito.</strong> Hay que inmovilizar más valor del que se obtiene. Eso no es un defecto: es lo que sustituye a la confianza.</p></li></ul><hr><h3>🌫️ Forma 3: sin respaldo</h3><p>El tercer diseño intenta sostener la promesa sin nada detrás: un mecanismo que emite y retira unidades según el precio se separe de su objetivo, confiando en que a alguien le convenga siempre corregir la diferencia.</p><p>Aquí se puede ser más rotundo que en el resto del curso, porque es un hecho y no una opinión: <strong>este diseño ha fallado varias veces, y ha fallado de la misma forma</strong>. Mientras hay calma funciona. Cuando la confianza se va, el mecanismo que debía corregir el precio empuja en la dirección contraria, y el hundimiento es rápido y total.</p><p>Lo que conviene entender es <em>por qué</em>, y es sencillo: <strong>el respaldo era la voluntad de otros de seguir participando</strong>. Y eso es justo lo que desaparece en el momento en que hace falta.</p><p>La plataforma no recomienda ni condena nada, y aquí no hace ninguna de las dos cosas: describe un diseño y lo que ha ocurrido con él cada vez.</p><hr><h3>🧭 Seis preguntas ante cualquiera de estas unidades</h3><ol><li><p><strong>¿Qué sostiene la promesa: una entidad, un depósito dentro, o nada?</strong> Es la primera y clasifica el resto.</p></li><li><p><strong>Si es una entidad, quién es y qué guarda exactamente.</strong> No «está respaldado»: qué, dónde y en qué proporción.</p></li><li><p><strong>Quién lo comprueba, cada cuánto, y si publica el informe.</strong> Una revisión periódica de un tercero no es lo mismo que una declaración propia.</p></li><li><p><strong>¿Quién puede congelar o anular unidades?</strong> Y si la respuesta es que nadie, ¿está comprobado o solo dicho?</p></li><li><p><strong>¿Puedes canjear tú, o dependes de que alguien te compre?</strong> Casi siempre es lo segundo. Saberlo cambia lo que estás teniendo.</p></li><li><p><strong>Si el respaldo está dentro: ¿de qué dato depende y qué pasa si la venta forzosa no llega a tiempo?</strong></p></li></ol><p>Y la regla de siempre: <strong>si una no tiene respuesta pública, eso ya es la respuesta</strong>.</p><hr><h3>💬 Por qué esta lección está en este curso</h3><p>Porque esto no es un asunto de ningún nicho: <strong>una parte enorme del movimiento de estas redes son estas unidades</strong>, y las usa gente que no va a tocar nunca nada más complicado. Dejarlo para un curso posterior sería dejarlo dos cursos tarde.</p><p>Y porque reúne todo lo anterior en un solo objeto: un token (Web3), un contrato con permisos de administración (2.2), un oráculo (1.3), una promesa que hace alguien de fuera (1.1) y un coste de ejecución que decide si puedes salir cuando quieras (1.2).</p><hr><h3>📌 En resumen</h3><ul><li><p>Valer siempre lo mismo <strong>no es una propiedad de la unidad: es una promesa</strong>, y alguien tiene que sostenerla.</p></li><li><p><strong>Respaldo fuera</strong>: lo promete una empresa y <strong>el registro no puede comprobarlo</strong>. No es un depósito, no hay fondo de garantía, y normalmente <strong>tú no puedes canjear</strong>: dependes del mercado.</p></li><li><p>Los contratos de este tipo suelen poder <strong>congelar o anular</strong> unidades de una dirección. Está en el código y se ha usado: <strong>no son dinero al portador</strong>.</p></li><li><p><strong>Respaldo dentro y sobrado</strong>: comprobable y sin empresa, pero <strong>depende de un dato de fuera</strong> y de que la venta forzosa funcione <strong>en el peor momento</strong>. Es ineficiente a propósito.</p></li><li><p><strong>Sin respaldo</strong>: ha fallado varias veces y de la misma forma, porque <strong>el respaldo era la voluntad de otros de seguir participando</strong>.</p></li><li><p>Seis preguntas: <strong>qué sostiene la promesa, quién es y qué guarda, quién lo comprueba, quién puede congelar, si puedes canjear tú, y de qué depende si el respaldo está dentro</strong>.</p></li></ul><hr><h3>➡️ Qué viene después</h3><p>Ya está todo el material. La última lección lo convierte en un método corto: <strong>seis preguntas que se responden mirando el contrato</strong>, no la web del proyecto, con la versión de tres para cuando no hay tiempo, lo que el método no te da, y por dónde seguir con lo que existe hoy en la plataforma.</p>')
ON CONFLICT (id) DO NOTHING;

-- 3.3 como-leer-un-contrato (7965 car)
INSERT INTO public.lessons (id, course_id, module_id, title, slug, description, order_index, content)
VALUES ('01782b5c-8b68-4aad-a00a-4283ea694357', 'd6f814e2-26d6-4d72-8e01-ce224fcde3f5', 'f1084f23-f381-4b10-96c2-6615dfb604ee', 'Cómo leer un contrato antes de tocarlo', 'como-leer-un-contrato', 'El método en seis preguntas, la versión corta en tres, lo que no te da y por dónde seguir con lo que existe hoy.', 2, '<h3>🎯 Objetivo de la lección</h3><p>Convertir el curso en un método corto: qué preguntar ante un contrato o una aplicación antes de tocarla, en qué orden, y qué hacer con las respuestas. Con la advertencia de lo que este método no te da y por dónde seguir con lo que existe hoy.</p><hr><h3>🧵 Lo que sostiene todo el curso</h3><p>Cuatro ideas. Con ellas se reconstruye el resto.</p><p><strong>1. Aquí el registro no anota: ejecuta.</strong> De ahí sale todo lo demás, empezando por que ejecutar cuesta y por que el coste es un peaje fijo que no depende de cuánto mueves.</p><p><strong>2. Un programa puede tener fondos, y no es nadie.</strong> Depositas en un texto que se ejecuta. Lo que pase depende de ese texto, y no hay a quién reclamar.</p><p><strong>3. Nada del mundo exterior entra solo.</strong> Un contrato es ciego: no sabe la hora, no puede mirar fuera y no puede sacar un número al azar. Todo lo que sepa del mundo <strong>se lo ha escrito alguien</strong>.</p><p><strong>4. El código no cambia; el comportamiento sí.</strong> La inmutabilidad protege las instrucciones que hay en una dirección, no tus condiciones.</p><p>Y por debajo, la pregunta de <em>Blockchain</em>, que aquí ha aparecido en cada lección: <strong>¿a cambio de qué?</strong></p><hr><h3>🧭 El método, en seis preguntas</h3><p>En este orden, porque las primeras descartan más rápido. Y todas se responden <strong>mirando el contrato y datos públicos</strong>, no la web del proyecto: eso ya lo cubría el método de <em>Qué es Web3 y qué no</em>, y este es el complementario.</p><p><strong>1. ¿Está el código publicado y verificado?</strong> Es decir: ¿lo que se puede leer es lo que se ejecuta? Es un dato que se consulta y se ve enseguida. Si no hay texto, o hay texto sin verificar, ya sabes en qué situación estás y las cinco preguntas siguientes valen menos.</p><p><strong>2. ¿La dirección reenvía a otra?</strong> Si reenvía, el comportamiento puede cambiar sin que cambie nada de lo que tú conoces.</p><p><strong>3. ¿Quién puede cambiarlo, con cuántas firmas y con cuánta demora?</strong> Una clave, varias, una votación, ninguna. Y si hay demora, cuánta: es lo único que te da tiempo a irte. Sin respuesta pública, estás en un sistema cuyas reglas cambia alguien a quien no has identificado.</p><p><strong>4. ¿De qué dato de fuera depende, y quién lo escribe?</strong> Si depende de un precio, de un resultado o de un hecho del mundo, ese es probablemente el punto más débil, y casi nadie lo mira.</p><p><strong>5. ¿Qué te está pidiendo firmar exactamente, y con qué tope?</strong> Una operación concreta o una autorización que sobrevive a la sesión. Sin tope y a un contrato que puede cambiar, autorizas lo que ese contrato llegue a ser.</p><p><strong>6. ¿Cuánto costaría salir, y de qué depende que puedas?</strong> Entrar y salir se pagan por separado. Y hay diseños en los que salir depende de que un tercero actúe, de que un plazo termine o de que alguien te compre.</p><p>Con seis respuestas concretas tienes una descripción que no depende de adjetivos. <strong>Y si alguna no tiene respuesta comprobable, eso ya es la respuesta.</strong></p><hr><h3>⏱️ La versión de tres preguntas</h3><p>Cuando no hay tiempo para las seis:</p><ol><li><p><strong>¿Puedo leer lo que se ejecuta?</strong></p></li><li><p><strong>¿Quién puede cambiarlo, y con cuánto aviso?</strong></p></li><li><p><strong>¿Qué estoy firmando y con qué tope?</strong></p></li></ol><p>La segunda es la más reveladora, y la tercera la única que depende solo de ti.</p><hr><h3>⚠️ Lo que este método no te da</h3><p>Con la misma claridad que en los otros cursos.</p><p><strong>No dice si algo va a funcionar</strong>, ni si va a seguir existiendo, ni qué le pasará a su valor. Nadie lo sabe. El método describe de qué depende una cosa, no cómo acabará.</p><p><strong>No detecta un fallo en el código.</strong> Eso exige leer el código con criterio, no está a tu alcance ni al de la mayoría, y ya se dijo en la 2.1: de los cuatro caminos por los que sale el dinero, los dos primeros no los puedes evaluar. Lo que el método hace es <strong>dejarte claro cuánto estás confiando en que otros lo hayan hecho</strong>.</p><p><strong>Y no protege del riesgo que no es técnico.</strong> Entender esto a la perfección no impide que alguien se gane tu confianza. Eso está en <em>Seguridad básica en Bitcoin y criptomonedas</em>, y es lo que más fondos se lleva.</p><p>El riesgo de aprender a evaluar es creerse a salvo. <strong>Entender cómo funciona algo y acertar con ello son cosas distintas.</strong></p><hr><h3>🗣️ Dos formas de hablar de esto que conviene reconocer</h3><p><strong>«El código es ley.»</strong> Suena a garantía y describe mal lo que hay. Sí es cierto que el contrato hace lo que dice sin interpretar nada. Pero el código puede no ser legible, puede cambiarlo alguien, puede depender de un dato que le escriben, y su resultado puede ser catastrófico sin tener ningún fallo. Quien repite la frase suele omitir las cuatro cosas.</p><p><strong>«Todo esto es un casino.»</strong> También es cómodo, y falla en lo contrario: hay diferencias reales y comprobables entre un contrato verificado que nadie puede cambiar y uno ilegible con una sola llave detrás. Meterlos en el mismo saco ahorra el trabajo de mirar.</p><p>Lo que has visto no encaja en ninguna de las dos, y esa es la idea: <strong>hay propiedades concretas, comprobables una por una, y de ellas depende lo que te puede pasar.</strong></p><hr><h3>🧭 Por dónde seguir</h3><p>Solo con lo que existe hoy en la plataforma.</p><p><strong>Si vas a tocar algo con dinero real, lo primero es <em>Seguridad básica en Bitcoin y criptomonedas</em></strong>, en la ruta de Seguridad. Nada de este curso protege una clave mal guardada, y el cuarto camino de la 2.3 —tu propia firma— se combate ahí tanto como aquí.</p><p><strong>Si quieres comprobar por tu cuenta en vez de creerte lo que lees</strong>, <em>Nodos Bitcoin - Tu Soberanía Técnica</em> enseña a mantener una copia completa de un registro. Es de otra red y a propósito: la práctica de verificar sin intermediario es la misma, y es la forma de dejar de dar por buena la palabra de un servicio de consulta.</p><p><strong>Si algo de las piezas generales se quedó flojo</strong>, <em>Blockchain: lo que Bitcoin no es</em> tiene el estado compartido, las otras formas de consenso y las capas y puentes, que aquí se han dado por sabidos.</p><p>Y los huecos, dichos sin prometer fechas: <strong>los préstamos y mercados que funcionan con contratos, y las organizaciones que se gobiernan con votos, no están hoy en la plataforma</strong>. Tampoco la criptografía de debajo ni cómo se programa nada de esto. Cuando estén, se dirá.</p><hr><h3>📌 En resumen</h3><ul><li><p>Cuatro ideas sostienen el curso: <strong>el registro ejecuta</strong>, <strong>un programa puede tener fondos y no es nadie</strong>, <strong>nada del mundo entra solo</strong> y <strong>el código no cambia pero el comportamiento sí</strong>.</p></li><li><p>El método son seis preguntas: <strong>código verificado</strong>, <strong>si reenvía</strong>, <strong>quién puede cambiarlo y con cuánta demora</strong>, <strong>de qué dato depende</strong>, <strong>qué firmas y con qué tope</strong> y <strong>cuánto cuesta salir</strong>.</p></li><li><p>En versión corta: <strong>¿puedo leer lo que se ejecuta?</strong>, <strong>¿quién puede cambiarlo y con cuánto aviso?</strong> y <strong>¿qué firmo y con qué tope?</strong></p></li><li><p>Si una pregunta no tiene respuesta comprobable, <strong>eso ya es la respuesta</strong>.</p></li><li><p>El método <strong>no dice si algo funcionará</strong>, <strong>no detecta fallos en el código</strong> y <strong>no protege del riesgo que no es técnico</strong>.</p></li><li><p>Los dos discursos fáciles —«el código es ley» y «todo es un casino»— ahorran el trabajo de mirar. <strong>Hay propiedades concretas y comprobables, y de ellas depende lo que te puede pasar.</strong></p></li></ul>')
ON CONFLICT (id) DO NOTHING;

-- ============================================================================
-- 5. Quiz: 27 preguntas, 9 por modulo
-- ============================================================================
-- correct_answer es el INDICE (0-3) de la opcion correcta en options.
-- Reparto de la correcta: no siempre la misma posicion, y la opcion correcta
-- no es sistematicamente la mas larga (gana por 4,4 caracteres de media). El
-- resto del catalogo tiene ese sesgo en el 85% de sus 216 preguntas, asi que
-- se puede aprobar eligiendo la mas larga: anotado como pendiente en el plan.

-- M1 Qué añadió Ethereum
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('3b2cb791-1ebd-4490-ad11-28f420361e2a', '¿Qué distingue a una cuenta que es un programa de una cuenta que abre una clave?', 'Tiene código y memoria propia, pero no tiene clave: nadie puede firmar en su nombre, ni quien lo escribió. Y no vigila ni se despierta. Si algo tiene que ocurrir a una hora, alguien de fuera tiene que llamarlo a esa hora y pagar por la llamada: de ahí que existan servicios cuyo único trabajo es apretar botones a su hora, y que sean un punto de fallo.', '["Que cobra una comisión por cada operación que recibe y la acumula en su saldo","Que no tiene clave y no puede empezar nada: solo se ejecuta cuando alguien la llama","Que solo puede recibir fondos y nunca enviarlos, salvo que su autor lo autorice","Que la gestiona la fundación que mantiene la red y responde de lo que haga"]'::jsonb, 1, 1, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('3b2cb791-1ebd-4490-ad11-28f420361e2a', '¿Cuál es la pieza que no tiene equivalente en Bitcoin?', 'En Bitcoin los fondos están siempre bloqueados a una condición: quien la cumpla puede gastarlos. Aquí una de las cuentas con saldo puede ser un programa entero. Tres consecuencias: depositas en algo que no es nadie, lo que ocurra depende de un texto que alguien escribió, y no hay a quién reclamar.', '["Que un programa pueda tener fondos propios","Que las operaciones se firmen con una clave privada","Que el registro sea público y permanente","Que exista una moneda nativa de la red"]'::jsonb, 0, 2, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('3b2cb791-1ebd-4490-ad11-28f420361e2a', 'Tienes un token en tu cuenta pero no tienes ether. ¿Qué ocurre?', 'Ejecutar cuesta y se paga en la moneda nativa, también cuando lo que mueves no es ella. No es un fallo ni una trampa: es la consecuencia directa de que este registro no anote pagos, sino que ejecute. Tener algo y no poder tocarlo es el diseño funcionando.', '["Puedes moverlo, pero la operación tarda bastante más en confirmarse de lo normal","El token queda bloqueado automáticamente hasta que ingreses ether en esa cuenta","No puedes moverlo: mover un token es llamar a un programa, y ejecutar se paga en ether","Puedes moverlo y la comisión se descuenta del propio token que estás enviando"]'::jsonb, 2, 3, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('3b2cb791-1ebd-4490-ad11-28f420361e2a', '¿Por qué la red cobra por ejecutar?', 'Es una defensa, no un modelo de negocio. Cada operación elemental tiene un coste fijado por el protocolo, y quien ordena la ejecución declara cuánto trabajo está dispuesto a pagar como máximo. Cuando se agota, la ejecución se para. Es la misma idea que la prueba de trabajo de Bitcoin —hacer que participar cueste— aplicada a otra cosa.', '["Para financiar el desarrollo del protocolo y pagar a quienes mantienen la red","Porque nada impediría mandarle un programa que no terminara nunca y bloquear a todos","Porque el espacio de almacenamiento de la cadena está limitado por el protocolo","Para que la moneda nativa tenga demanda constante y no pierda valor con el tiempo"]'::jsonb, 1, 4, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('3b2cb791-1ebd-4490-ad11-28f420361e2a', 'Tu operación se queda sin trabajo disponible a mitad de ejecución. ¿Qué pasa?', 'No queda nada a medias: el estado vuelve exactamente a como estaba. Y se paga igual, porque los que mantienen la red hicieron el trabajo de ejecutar hasta ahí. Si el intento fallido fuera gratis, atacar la red sería gratis: bastaría con mandar operaciones destinadas a fallar.', '["Se queda pendiente y se reanuda cuando pagues el resto","Se cancela y se te devuelve lo pagado, menos una pequeña penalización","El estado vuelve a como estaba y se paga todo lo consumido","Se ejecuta la parte que llegó a hacerse y el resto se descarta"]'::jsonb, 2, 5, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('3b2cb791-1ebd-4490-ad11-28f420361e2a', '¿Por qué se dice que una red muy usada expulsa antes al usuario pequeño?', 'Enviar el equivalente a cinco euros y a cincuenta mil cuesta lo mismo. Un peaje fijo no afecta a todos igual: si se acerca a lo que quieres mover, tu operación deja de tener sentido, mientras para quien mueve mil veces más sigue siendo irrelevante. Así que la red no se encarece para todos, deja fuera a los de abajo.', '["Porque el protocolo da menos prioridad a las operaciones pequeñas si hay congestión","Porque el coste depende de lo que la red tenga que hacer, no de cuánto mueves: es un peaje fijo","Porque la comisión es un porcentaje de la cantidad enviada y sube con la congestión","Porque las cuentas con poco saldo pierden el acceso temporalmente cuando la red se llena"]'::jsonb, 1, 6, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('3b2cb791-1ebd-4490-ad11-28f420361e2a', '¿Por qué un contrato no puede sacar un número verdaderamente al azar?', 'La ejecución tiene que ser determinista: mismas entradas, misma salida, siempre. Lo que parezca aleatorio sale de datos del propio registro, y quien construye el bloque influye en esos datos o simplemente no incluye la operación si no le conviene. Cualquier reparto que dependa de un azar así es manipulable por quien ordena las operaciones.', '["Porque generar azar de verdad exigiría tanto cómputo que las operaciones serían inasumibles","Porque la máquina virtual no incluye las instrucciones matemáticas que harían falta para ello","Porque el azar solo está disponible en las capas construidas encima de la cadena principal","Porque todos los que mantienen una copia deben obtener el mismo resultado, y el azar es lo contrario"]'::jsonb, 3, 7, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('3b2cb791-1ebd-4490-ad11-28f420361e2a', '¿Qué es exactamente un oráculo, y por qué el nombre engaña?', 'El nombre suena a mecanismo y no lo es: es una parte que escribe. Un contrato no puede consultar nada de fuera, así que todo lo que sepa del mundo se lo ha escrito alguien. De ahí que un contrato sin ningún fallo pueda comportarse de forma catastrófica: el dato del que dependía era falso, y él hizo exactamente lo que decía.', '["Alguien que anota dentro del registro un dato de fuera, que el contrato da por bueno sin comprobarlo","Un mecanismo del propio protocolo que consulta en internet los precios y datos que el contrato necesita","Un contrato especial que tiene permiso para leer el estado de otras cadenas y traerlo a la suya","Un tipo de nodo cuya función es comprobar que los datos externos que entran son correctos"]'::jsonb, 0, 8, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('3b2cb791-1ebd-4490-ad11-28f420361e2a', '¿Cuál de estas formas de fallar un dato externo no requiere que nadie mienta?', 'Si el dato refleja el precio de un mercado pequeño, alguien con suficiente dinero puede moverlo unos segundos, hacer que el contrato valore algo mal y aprovecharlo. El oráculo informó de un precio real. Y esto desmonta el consuelo de «viene de varias fuentes independientes»: varias fuentes que miran el mismo mercado delgado coinciden todas en el precio manipulado.', '["Que quien escribe el dato sea coaccionado para escribir otro valor","Que el dato sea cierto, y alguien mueva a propósito el mercado que mide","Que el contrato no compruebe la antigüedad del dato que está leyendo","Que el dato venga de una sola fuente en vez de varias independientes"]'::jsonb, 1, 9, 'medium', 1);

-- M2 Lo que decide si algo falla
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('f9e7695b-5f04-47f7-9ae9-f468676a4dc0', '¿Qué hay realmente en la dirección donde alguien ha publicado un contrato?', 'La red no ha visto nunca el texto original y no lo necesita: ejecuta la traducción a instrucciones, que es ilegible para una persona. El texto legible vive en un repositorio, una web o un explorador, fuera de la cadena. Así que lo que tú lees y lo que se ejecuta llegaron por caminos distintos.', '["El texto que escribió quien lo programó, tal cual, con sus comentarios incluidos","Un enlace al repositorio donde está publicado el código fuente y su licencia","Instrucciones para la máquina virtual; el texto legible, si existe, está fuera","Una copia cifrada del código que solo puede descifrar quien tenga la clave del autor"]'::jsonb, 2, 1, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('f9e7695b-5f04-47f7-9ae9-f468676a4dc0', '¿Qué significa que el código de un contrato esté «verificado»?', 'No lo hace el protocolo: lo hacen servicios de consulta, fuera de la red, así que te fías de que lo hicieran bien. Pero cualquiera puede repetir la comprobación, y eso la distingue de una promesa. Verificado significa legible, no bueno. Lo peor de las tres situaciones posibles es texto publicado sin verificar, porque parece transparencia.', '["Que un auditor independiente ha certificado que no tiene fallos conocidos","Que alguien tradujo otra vez el texto publicado y coincide con lo que hay dentro","Que el propio protocolo comprobó el código antes de aceptar su publicación","Que el contrato ha funcionado sin ningún incidente durante el plazo mínimo exigido"]'::jsonb, 1, 2, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('f9e7695b-5f04-47f7-9ae9-f468676a4dc0', 'De todo lo que una auditoría no garantiza, ¿cuál es la omisión que más veces se pasa por alto?', 'Todas son ciertas, pero esta es la que casi nadie comprueba. La auditoría cubre la versión que revisaron; si el contrato se puede cambiar, lo que corre ahora puede no ser lo auditado. De ahí que un informe sin fecha ni versión exacta no diga nada, y que un sello sin documento descargable sea una afirmación, no una auditoría.', '["Que quien audita no responde en modo alguno de tus pérdidas","Que no demuestra que el contrato no tenga ningún fallo","Que puede no cubrir el código que se está ejecutando hoy","Que no revisa el diseño económico del proyecto que lo usa"]'::jsonb, 2, 3, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('f9e7695b-5f04-47f7-9ae9-f468676a4dc0', 'Si el código de un contrato no se puede modificar, ¿cómo es que los proyectos actualizan sus contratos?', 'La dirección con la que tratas no contiene la lógica: contiene una nota que reenvía las llamadas a otra dirección, y esa nota se puede reescribir. Tu dirección no ha cambiado, tu saldo sigue ahí, y las reglas que lo gobiernan son otras desde hace un bloque. La inmutabilidad protege el código, no tus condiciones.', '["Se publica lógica nueva en otra dirección y se reescribe la nota que dice dónde está","Se vota una excepción entre quienes mantienen la red y se aplica en el bloque siguiente","Se sobrescriben las instrucciones de esa dirección pagando un coste mucho mayor","Se crea una bifurcación de la cadena cada vez que hay que actualizar un contrato"]'::jsonb, 0, 4, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('f9e7695b-5f04-47f7-9ae9-f468676a4dc0', '¿Para qué sirve de verdad que un cambio tenga que esperar un plazo antes de aplicarse?', 'La demora no impide el cambio, y ahí está su valor: convierte una decisión ajena en algo que puedes ver venir. Sin demora, la garantía es la buena voluntad de quien tiene la llave. Y ojo con la votación: si unos pocos concentran la mayoría, es una sola clave con un trámite. Se mira en el reparto, no en el reglamento.', '["Para que la comunidad pueda votarlo y rechazarlo durante ese plazo si no le conviene","Para impedir que el cambio llegue a producirse si aparece oposición suficiente","Para que haya tiempo de corregir errores en el código nuevo antes de aplicarlo","Para darte tiempo a irte: es la diferencia entre enterarte antes y enterarte después"]'::jsonb, 3, 5, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('f9e7695b-5f04-47f7-9ae9-f468676a4dc0', '¿Qué quiere decir que «inmutable» no significa «sin dueño»?', 'Son poderes que no requieren cambiar el código porque el código ya los previó: pausar —que a veces impide también sacar—, mover un parámetro, añadir o quitar direcciones de una lista, y la vía de emergencia pensada para rescatar, que es la misma que sirve para vaciar. Un contrato que alguien puede cambiar a su gusto y sin demora es un servicio gestionado por ese alguien, con pasos de más.', '["Que siempre hay alguien que cobra una comisión por cada uso y puede subirla","Que el código sigue perteneciendo legalmente a su autor aunque esté publicado","Que un contrato imposible de cambiar puede permitir pausar, mover parámetros o retirar fondos","Que la red puede revertir lo que haya hecho un contrato si se alcanza consenso suficiente"]'::jsonb, 2, 6, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('f9e7695b-5f04-47f7-9ae9-f468676a4dc0', '¿Cuál es el patrón general del fallo llamado reentrada?', 'Mandar dinero a una cuenta que es un programa ejecuta ese programa, que puede volver a entrar antes de que el primero haya apuntado que ya pagó. El caso de 2016 acabó con un contrato vaciado y la red partida en dos al deshacerlo: la única vez que la respuesta a un fallo de un contrato fue reescribir el registro.', '["Que dos usuarios distintos ejecutan la misma operación dentro del mismo bloque","Que el contrato dio por supuesto que nada pasaría entre dos de sus propios pasos","Que el contrato se queda sin fondos suficientes para atender todas las retiradas","Que un contrato llama a otro contrato que nadie ha llegado a revisar ni verificar"]'::jsonb, 1, 7, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('f9e7695b-5f04-47f7-9ae9-f468676a4dc0', 'De los cuatro caminos por los que sale el dinero de un contrato, ¿cuáles no son fallos de nada?', 'Los dos últimos son el sistema funcionando como está diseñado. Nadie rompió nada: alguien usó un permiso que el contrato le concede, o tú firmaste algo válido. Y esa distinción importa más que la lista, porque cambia por completo lo que puedes hacer al respecto.', '["El orden imprevisto y el dato de fuera","El dato de fuera y tu propia firma","Alguien con permiso y tu propia firma","El orden imprevisto y alguien con permiso"]'::jsonb, 2, 8, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('f9e7695b-5f04-47f7-9ae9-f468676a4dc0', '¿Cuál de los cuatro caminos puedes comprobar por tu cuenta con datos públicos, sin leer código?', 'Los dos primeros caminos no puedes evaluarlos: exigen leer el código y entender de qué se fía el contrato. El tercero es el que más gente se salta pudiendo no saltárselo, porque son cuatro datos públicos. Y el cuarto, tu firma, es enteramente tuyo y no depende de la calidad de nada.', '["El orden imprevisto, mirando cuánto lleva funcionando el contrato con dinero dentro","El dato de fuera, comparando el precio que usa el contrato con los de otros mercados","Ninguno de los cuatro: los cuatro exigen conocimientos que no están al alcance de un usuario corriente","Quién tiene permiso: si la dirección reenvía, quién puede cambiarlo, si hay demora y si hay historial"]'::jsonb, 3, 9, 'medium', 1);

-- M3 Lo que te vas a encontrar
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('f1084f23-f381-4b10-96c2-6615dfb604ee', 'Firmas una operación, se queda esperando, y las siguientes tampoco se ejecutan aunque ofrezcas pagar más. ¿Por qué?', 'La número 8 no se ejecuta hasta que se haya ejecutado la 7, y no hay adelantamiento por la derecha. Además, una operación enviada no se puede cancelar: está firmada y es pública, así que cualquiera puede incluirla. Solo se puede sustituir, firmando otra con el mismo número y pagando más. Mientras espere, puede ejecutarse en cualquier momento.', '["Porque la red penaliza a las cuentas que reintentan demasiadas veces seguidas","Porque las operaciones de una misma cuenta van numeradas y en orden estricto","Porque hay que esperar a que la primera operación caduque y se descarte sola","Porque el contrato bloquea la cuenta mientras hay una operación pendiente"]'::jsonb, 1, 1, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('f1084f23-f381-4b10-96c2-6615dfb604ee', 'Tu operación se ejecuta exactamente como la pediste, pero recibes menos de lo que viste en pantalla. ¿Qué ha pasado?', 'Mientras espera, tu operación es legible: qué vas a hacer, con qué contrato y por cuánto. Y quien construye el bloque elige el orden, así que puede colocar la suya antes, mover el precio y deshacerla después. De ahí el margen de tolerancia, que tiene dos caras: estrecho hace que la operación falle a menudo —y se paga igual—; amplio autoriza por adelantado un resultado malo.', '["La aplicación calculó mal la comisión y te descontó la diferencia de lo que recibías","Parte de lo recibido se queda retenido hasta que la operación acumule otra confirmación","Mientras esperaba era pública, y quien construye el bloque puso otra operación antes","El contrato aplicó una comisión adicional que no estaba anunciada en la pantalla"]'::jsonb, 2, 2, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('f1084f23-f381-4b10-96c2-6615dfb604ee', '¿Qué tiene de particular una autorización, frente a firmar una operación concreta?', 'Es una casilla que dice que otra dirección puede mover hasta tanto de lo que tienes. Es por contrato y por token, así que se acumulan sin que te enteres; no caduca; y quitarla es una operación con su coste. La combinación que ordena el curso: una autorización sin tope a un contrato que alguien puede cambiar es una autorización a lo que ese contrato llegue a ser.', '["Que se puede revocar sin ningún coste desde la propia aplicación que la pidió","Que caduca automáticamente en cuanto cierras la sesión en la web que la pidió","Que solo permite mover la cantidad exacta que pactaste al concederla","Que no caduca, suele pedirse sin tope, y sigue viva aunque el contrato cambie después"]'::jsonb, 3, 3, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('f1084f23-f381-4b10-96c2-6615dfb604ee', 'Te piden una firma que no cuesta nada y no aparece como operación en ningún sitio. ¿Qué conviene suponer?', 'Suenan inofensivas precisamente porque no pasa nada y no se paga nada. Pero una de esas firmas puede valer como autorización o como una orden que alguien ejecutará cuando le convenga. Que algo sea gratis e invisible no significa que no autorice nada.', '["Que es inofensiva, porque no llega a modificar el estado del registro en ningún momento","Que puede autorizar que otro mueva tus fondos después, y el coste lo pagará quien la use","Que solo puede servir para demostrar ante quien la pide que controlas esa cuenta","Que caducará al cabo de unos minutos si nadie llega a utilizarla para nada"]'::jsonb, 1, 4, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('f1084f23-f381-4b10-96c2-6615dfb604ee', 'Una unidad que promete valer siempre un euro y cuyo respaldo está fuera del registro: ¿qué tienes exactamente?', 'Los contratos son ciegos a todo lo de fuera, así que ninguna propiedad de la cadena te dice si el respaldo existe. No es un depósito: no hay fondo de garantía. Y el canje directo suele estar reservado a clientes grandes con contrato, así que dependes de que alguien te compre las unidades en un mercado. Qué respalda importa tanto como cuánto.', '["Un depósito con una garantía equivalente a la de una cuenta bancaria, respaldada por el emisor y su banco","Un derecho de canje frente al emisor, ejecutable en cualquier momento y por cualquier cantidad que tengas","La promesa de una empresa que el registro no puede comprobar, y el precio de mercado en vez del canje","Una unidad cuyo respaldo garantiza el propio protocolo de la red en la que se emite y se mueve"]'::jsonb, 2, 5, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('f1084f23-f381-4b10-96c2-6615dfb604ee', '¿Por qué se dice que estas unidades no son dinero al portador?', 'Es la versión fuerte de las listas de direcciones: está en el código, es una capacidad documentada y se ha usado. No es una puerta trasera oculta: existe porque la entidad emisora tiene obligaciones legales que cumplir. Tener la clave no garantiza poder moverlas, y eso las separa por completo del bitcoin y del ether.', '["Porque hace falta identificarse ante el emisor antes de poder recibirlas o enviarlas","Porque solo pueden moverse durante el horario en el que el emisor está operativo","Porque su contrato suele poder impedir que una dirección las mueva, e incluso anularlas","Porque su valor cambia dependiendo de la red en la que se emitan y se utilicen"]'::jsonb, 2, 6, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('f1084f23-f381-4b10-96c2-6615dfb604ee', 'El diseño que sostiene la promesa sin ningún respaldo ha fallado varias veces de la misma forma. ¿Por qué?', 'Mientras hay calma funciona. Cuando la confianza se va, el mecanismo que debía corregir el precio empuja en la dirección contraria y el hundimiento es rápido y total. No es una opinión sobre el diseño: es lo que ha ocurrido con él cada vez.', '["Porque el respaldo era la voluntad de otros de seguir participando, que es lo que desaparece","Porque los contratos que lo implementaban compartían un fallo que acabó explotándose","Porque los reguladores intervinieron en el momento crítico y bloquearon el mecanismo","Porque el oráculo del que dependían dejaba de actualizar el precio en el peor momento"]'::jsonb, 0, 7, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('f1084f23-f381-4b10-96c2-6615dfb604ee', 'Aplicas el método y una de las seis preguntas no tiene respuesta pública. ¿Qué haces con eso?', 'No es una sospecha, es una descripción. Si no se sabe quién puede cambiar las reglas, estás en un sistema cuyas reglas cambia alguien a quien no has identificado. Es la misma regla que en Blockchain, y aquí se aplica igual.', '["Buscar la respuesta preguntando en los canales oficiales de la comunidad del proyecto","Descartar esa pregunta y decidir con lo que digan las respuestas de las otras cinco","Tratarla como respuesta: describe un sistema del que no sabes algo que sí se puede saber","Suponer la opción más probable a partir de lo que digan las respuestas restantes"]'::jsonb, 2, 8, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('f1084f23-f381-4b10-96c2-6615dfb604ee', '¿Qué es lo que este método no te da?', 'El método describe de qué depende una cosa, no cómo acabará. No detecta fallos: eso exige leer código con criterio, y lo que hace es dejarte claro cuánto estás confiando en que otros lo hayan hecho. Y no protege de que alguien se gane tu confianza, que es lo que más fondos se lleva. El riesgo de aprender a evaluar es creerse a salvo.', '["Saber quién puede cambiar un contrato, con cuántas firmas hacen falta y con cuánta demora","Saber si el código que puedes leer es el que se ejecuta y si alguien lo ha revisado","Saber de qué dato de fuera depende un contrato y quién es exactamente el que lo escribe","Saber si algo va a funcionar, detectar un fallo en el código y protegerte del riesgo no técnico"]'::jsonb, 3, 9, 'medium', 1);

