-- ============================================================================
-- 7. Devolver el curso a 'published' (regla 22)
-- ============================================================================

UPDATE public.courses SET status = 'published', updated_at = now()
 WHERE slug = 'ethereum-y-contratos-inteligentes' AND status = 'pending_review';

COMMIT;


